const PRESS_WORKS=[{id:"w1",title:"The Cartographer's Confession",author:US[1],excerpt:"The first map I ever drew was a lie. I was nine, and my father had asked me to sketch the walk from our house to the schoolyard…",words:3200,form:"fiction",tags:["Literary Fiction","Magical Realism"],moods:["Haunting","Lush"],attested:true,likes:312,comments:87,shelved:94,readTime:13,featured:true,note:"A debut that reads like a myth being remembered.",lens:"storyteller"},{id:"w2",title:"Inheritance Tax",author:US[4],excerpt:"My grandmother left me her tongue. Not the language — I already had that, the Tamil she'd fed me like rice water when I was small…",words:1800,form:"essay",tags:["Memoir"],moods:["Tender","Elegiac"],attested:true,likes:489,comments:124,shelved:183,readTime:7,featured:true,note:"Inheritance as vocal cord, not document.",lens:"empath"},{id:"w3",title:"What the River Kept",author:{...US[2],name:"Amira Khalil"},excerpt:"I did not drown.\nThe river had its reasons\nfor releasing me —\n\nsomething about the way\nI held my breath\nlike a prayer I didn't believe in.",words:180,form:"poetry",tags:["Free Verse"],moods:["Quiet","Haunting"],attested:true,likes:267,comments:43,shelved:198,readTime:1,featured:true,note:"Every line break is a held breath.",lens:"empath"},{id:"w4",title:"Aubade for the Algorithm",author:{...US[5],name:"Nina Okafor",in:"NO",ink:2900},excerpt:"Good morning, machine.\nI have fed you my reading list,\nmy search history,\nthe 3 a.m. poems I wrote\nand deleted before the screen\ncould memorize my grief.",words:240,form:"poetry",tags:["Free Verse","Experimental"],moods:["Sharp","Playful"],attested:true,likes:567,comments:134,shelved:389,readTime:1,featured:true,note:"The best poem about AI is the most human one here.",lens:"philosopher"},{id:"w5",title:"On Rereading Beloved at Forty",author:{...US[3],name:"David Chen",in:"DC",ink:5600},excerpt:"The first time I read Beloved I was twenty-two and I thought it was about slavery. Now I am forty and I understand it is about the price of a self…",words:2100,form:"essay",tags:["Cultural Criticism","Craft / Writing"],moods:["Meditative","Warm"],attested:true,likes:178,comments:89,shelved:134,readTime:8,featured:false,lens:"philosopher"}];
