const BOOK_DATA={
"Beloved":{title:"Beloved",author:"Toni Morrison",year:1987,publisher:"Alfred A. Knopf",pageCount:321,rating:4.8,ratingsCount:485230,genres:["Literary Fiction","Historical Fiction"],cc:"#6A2A3A",description:"Sethe, an escaped enslaved woman living in post-Civil War Ohio, is haunted — literally and figuratively — by the trauma of her past. Her home at 124 Bluestone Road is possessed by the malevolent ghost of her baby daughter. When a mysterious young woman calling herself Beloved arrives, memory collapses into the present and the past demands to be reckoned with.",pages:["124 was spiteful.\n\nFull of a baby's venom. The women in the neighborhood had taken their fright and gone back to their own lives. Sethe and her daughter Denver were its only victims. The grandmother, Baby Suggs, had died eight years before and the sons, Howard and Buglar, had run away by the time they were thirteen years old — as soon as merely looking in a mirror shattered it.","The day Paul D showed up, Sethe was working at her regular place and he appeared in the back, leaning against the fence. She recognized him before she could name him — the way you recognize a voice on a quiet night, from across a yard, from years before.\n\nHe had come a long way. She could see it in the way he held himself, careful, like something might fall off if he moved too fast.","Beloved sat at the table and would not move. She wanted to eat from Sethe's plate, to sleep in Sethe's bed, to own every minute of her mother's time.\n\nDenver watched all this from the doorway. She had waited years for a companion, for anyone. Now that she had one, she wasn't sure what to do with the wanting that had kept her company all that time.","Memory in this house had its own geography. Sethe walked around certain spots the way you walk around a crack in the floor that has always been there — not because you can't fix it, but because by now it belongs to the house.\n\nBaby Suggs used to say the past wasn't gone. It was just resting.","Paul D found the tobacco tin in his chest useful. Everything he could not carry openly, he put in there. By the time he arrived at 124 he thought nothing could get through that metal, that rust.\n\nHe was wrong about that, like he had been wrong about other things. But the being wrong was part of it. The being wrong was how you knew it had gotten in."]},
"Intermezzo":{title:"Intermezzo",author:"Sally Rooney",year:2024,publisher:"Farrar, Straus and Giroux",pageCount:464,rating:4.1,ratingsCount:127340,genres:["Literary Fiction","Contemporary"],cc:"#3A5A4A",description:"Brothers Peter and Ivan Koubek struggle to grieve their father's death. Peter is a Dublin lawyer in his thirties entangled between two women he cannot choose between. Ivan, ten years younger, is a chess prodigy who falls unexpectedly in love with an older woman. Their story is one of grief, eros, and the impossible distance between people who share the same blood.",pages:["The funeral was on a Thursday. Peter stood at the back of the church and watched his brother from a distance, the way you watch someone you know well but haven't spoken to in months — looking for changes, for clues.\n\nIvan had their father's hands. Peter had always known this but had never said it. Some observations are too fragile for language.","Peter called Sylvia at eleven o'clock that night. She picked up on the second ring, which meant she'd been awake, which meant she'd been thinking about him, which was the kind of information he had to be careful with.\n\n—Are you alright, she said.\n—I'm trying to be.\n\nOutside the window, Dublin was doing what it always did: existing, indifferently.","Ivan met Margaret at a chess club in a church hall on a wet Saturday in February. She was thirty-six. He was twenty-two. Neither of them mentioned the difference, which meant they were both thinking about it.\n\nShe played aggressively — sacrificing pieces early to control the center — and he found this interesting in a way that went beyond chess.","There was a word Peter kept using in his head that he would not say aloud: unfair. It was a child's word. He was thirty-two years old. He had built a life based on the premise that fairness was not a feature of the world but a direction you could choose to move in anyway.\n\nHis father had believed this too. That was the part he hadn't accounted for.","Ivan thought about chess the way other people thought about God — as a system that explained things that otherwise didn't make sense. Not a comfort, exactly. More like a grammar.\n\nAfter Margaret, he started to understand that some things couldn't be grasped through systems. Some things you just had to hold, even when your arms weren't strong enough."]},
"Orbital":{title:"Orbital",author:"Samantha Harvey",year:2023,publisher:"Jonathan Cape",pageCount:209,rating:4.0,ratingsCount:89430,genres:["Literary Fiction","Science Fiction"],cc:"#2A3A6A",description:"Six astronauts aboard the International Space Station orbit the earth sixteen times a day. As they watch continents drift beneath them and hold the threads of their lives on the planet below, the novel becomes a meditation on time, beauty, impermanence, and what it means to be human when the world you come from has become a small blue thing in the dark.",pages:["They circle the earth sixteen times in a day. Sixteen sunrises, sixteen sunsets. The day has no length here, only frequency. Below them, the planet turns at its own indifferent pace.\n\nSometimes one of them will press a hand to the window without knowing why — an instinct older than thought, reaching for something that isn't there anymore.","The ISS hums. It hums the way old buildings hum, full of systems working so you don't have to think about them. Electricity, atmosphere, the constant maintenance of the possible.\n\nRoman watches clouds mass over the Bay of Bengal. He grew up near the Black Sea and still searches for it each pass, the way you look for your childhood home on a map — not because you want to go back, but because you want to confirm it exists.","A message comes from Chie's mother: her father is worse. Chie reads it three times. In the cupola, looking down at Japan — so small from here, so particular — she thinks about the smallness of the body and the largeness of what it contains.\n\nThey have to get on with it. This is what astronauts know that nobody mentions in the brochures.","They eat together when they can. The food is not good but the eating together is good. Nell has started a list of things she misses: rain, specifically, and the sound it makes on a roof. Her cat's weight at the foot of the bed. The smell of coffee before it's been made into coffee.\n\nThe list has fifty-three items.","From up here, the border between Pakistan and India is not visible. This is the kind of knowledge that is obvious from a distance and impossible on the ground. They carry it with them on every pass — this other way of seeing — and they don't quite know what to do with it yet."]},
"The Vegetarian":{title:"The Vegetarian",author:"Han Kang",year:2007,publisher:"Portobello Books",pageCount:188,rating:4.1,ratingsCount:312400,genres:["Literary Fiction","International","Psychological"],cc:"#4A6A3A",description:"After Yeong-hye has a violent, vivid nightmare, she stops eating meat. What follows — told through three perspectives — is a slow-building account of a woman's radical act of bodily refusal and the chaos it unleashes in those around her. Han Kang writes about autonomy, violence, and womanhood with a precision that feels almost unbearably close.",pages:["Before my wife turned vegetarian, I'd always thought of her as completely unremarkable in every way. To be frank, the first time I met her I wasn't even attracted to her.\n\nShe was the kind of woman who blended into any background. She dressed simply, spoke simply, expected very little. This, I had thought, would make my life easier. I had been right about that, until I was wrong.","The dream, she told me, had been full of meat. Flesh hanging in a dark place. Her own hands.\n\nShe would not elaborate. I pressed her for details in the way you press someone you live with, assuming access, and she turned away from me in the way a door turns when you haven't got a key.","Yeong-hye's sister In-hye ran the household the way practical people run things: systematically, without complaint, keeping track of what needed keeping track of. She had always considered her sister fragile in some basic way, like an object not meant for daily use.","There is a painting in the mind of a man who looks at Yeong-hye and sees something he wants to translate onto skin — hers and his — because he cannot stop thinking about flowers and bodies and the place where the two might become indistinguishable.\n\nDesire is like that. It makes you want to turn people into something you can keep.","In-hye thinks about endurance constantly now. How it works. Whether it has a mechanism or whether it is just what happens when there is no alternative.\n\nEndurance, she has come to believe, is just another word for continuing to be present in a life you did not entirely choose."]},
"James":{title:"James",author:"Percival Everett",year:2024,publisher:"Doubleday",pageCount:303,rating:4.4,ratingsCount:98760,genres:["Historical Fiction","Literary Fiction"],cc:"#5A3A2A",description:"A retelling of Adventures of Huckleberry Finn from the perspective of Jim — here called James — the enslaved man who accompanies Huck down the Mississippi. Everett gives James an interior life of astounding complexity: educated, philosophical, navigating a world that refuses to see him. Funny, devastating, and formally inventive.",pages:["When the white people were around, we talked like they expected us to talk. It wasn't stupidity that made us do it — it was the opposite of stupidity. A kind of genius, if you want to call it that: the genius of knowing what is expected and giving it, while holding the rest somewhere they can't reach.\n\nMy name is James. That is the first thing you should know.","Huck was a white boy who didn't know he was performing whiteness, which is, of course, the whole point of whiteness. He was kind in the way that people are kind when they haven't yet been asked to choose between kindness and comfort.\n\nI liked him. I was aware, at all times, of exactly how much that liking could cost me.","The river doesn't care about any of this. That's what I kept coming back to, drifting down it at night, listening to it.\n\nThe river predates the argument about who owns whom. It predates the whole vocabulary. Watching the water, I thought: this is what it would feel like to exist outside of their story. Just for a moment.","At night I wrote in the margins of books they didn't know I could read. Locke. Voltaire. I wrote in a hand so small it looked like the printer's error. If they found it they would see marks. They wouldn't see what the marks meant. That distinction had kept me alive.","Freedom is not a place. I had to learn this. It is not a state across a river or a city with a different name for what it does to people. It is something you carry or you don't, and carrying it does not mean you are free, only that you haven't put it down yet.\n\nI'm still carrying it. That is the most honest thing I can tell you."]},
"Demon Copperhead":{title:"Demon Copperhead",author:"Barbara Kingsolver",year:2022,publisher:"Harper",pageCount:560,rating:4.3,ratingsCount:201870,genres:["Literary Fiction","Historical Fiction"],cc:"#7A4A2A",description:"A retelling of David Copperfield set in the opioid-ravaged mountains of Appalachia. Damon Fields — Demon Copperhead — narrates his own story: foster care, football, first love, and the painkiller that waits at the end of every tunnel. Kingsolver writes with fierce love for a place and people that the rest of the country has decided are disposable.",pages:["First, I got myself born. That's step one in any life worth the telling.\n\nThe where: Lee County, Virginia. The when: end of the nineteen-eighties, which is later than it sounds if you're talking about the mountains. Some things arrive late to us up here, and some things we were the first to get, and opioids were the second kind.","My mother was not a bad person. I want to say that clearly, at the start, before the complications. She was a person who had been given a set of tools that weren't up to the job, and she used them as best she could, which was not well.\n\nI loved her. I still do. That's also a complication.","Football was the one place where being big and fast and not afraid of pain was an asset instead of a liability. Coach was the first adult who ever looked at me and saw something that could be used — not against me, but for something.\n\nI understand now that this is a low bar. At the time it felt like being chosen.","The pill dissolved and everything softened. Not disappeared — softened. The edges of things became negotiable. My arm, which had been screaming since the second quarter, had decided to forgive me.\n\nI thought: so this is what they mean by relief. I didn't understand yet that relief was the opposite of free.","You want to know about the mountains, I'll tell you: they're beautiful the way all things are beautiful when they're indifferent to you. The leaves turn and the creeks run and the hawks circle and none of it is doing any of it for your benefit.\n\nWe are born here and most of us die here and the mountains continue, and that's not tragedy. That might be the only honest thing."]},
"Creation Lake":{title:"Creation Lake",author:"Rachel Kushner",year:2024,publisher:"Scribner",pageCount:400,rating:3.9,ratingsCount:42180,genres:["Literary Fiction","Thriller"],cc:"#5A4A6A",description:"Sadie Smith is an American spy embedded in a French radical commune. She is brilliant, ruthless, and completely unreliable as a narrator. Through her sharp observations — and through the strange, beguiling letters of an underground philosopher she intercepts — a novel about ideology, surveillance, and the stories we construct to justify ourselves.",pages:["My name, this week, is Sadie Smith. It's a good name for the work: plain, American, slightly forgettable. The kind of name that makes people feel like they already know you.\n\nI've been in the Lot Valley for three weeks. I'm here to dismantle a small network of people who believe, earnestly, that the old ways of living constitute a political act. My job is to disagree with them, professionally.","Bruno Lacombe writes his letters from a cave. Not metaphorically — literally, from a cave in the Dordogne where he has been living for some months in voluntary exile from a civilization he considers terminal.\n\nI intercept his letters. He doesn't know this. He writes with the assurance of someone who believes his words are going somewhere safe. This is my favorite kind of subject.","The commune operates on the principle that sincerity is a form of resistance. They mean this. They grow their own vegetables and argue about Kropotkin and look at each other with a directness that makes most people uncomfortable.\n\nI find them moving and foolish, which is how I find most idealists. The moving part is real. The foolish part is the problem.","What Bruno understands — and what his comrades miss — is that the Neanderthal didn't fail. The Neanderthal lasted three hundred thousand years. It is we who are the experiment, and the results are not yet in.\n\nI read his letters a second time, which I don't usually do. There's something in the syntax I want to understand.","Sadie Smith has excellent cover and no interiority. This is a professional asset. You can't get at someone who has managed to locate themselves entirely in the surface of things.\n\nAt night I think about Bruno in his cave, writing by lamplight to people who will never fully understand him, and I think about sincerity, and whether it is possible to have a self you haven't performed into existence."]}
};

// ─── CSS ─────────────────────────────────────────────────────
const gc=T=>`@import url('https://fonts.googleapis.com/css2?family=Cormorant+Garamond:ital,wght@0,400;0,500;0,600;0,700&family=Source+Serif+4:ital,opsz,wght@0,8..60,300;0,8..60,400;0,8..60,500;1,8..60,400&family=Outfit:wght@300;400;500;600;700;800&family=JetBrains+Mono:wght@400;500&display=swap');*,*::before,*::after{box-sizing:border-box;margin:0;padding:0}html,body{background:${T.bg}!important;overflow-x:hidden;-webkit-tap-highlight-color:transparent;touch-action:pan-x pan-y;overscroll-behavior:none;height:100%}body{touch-action:pan-x pan-y}::selection{background:${T.gold}30;color:${T.tx}}::-webkit-scrollbar{width:0;height:0}@keyframes en{from{opacity:0;transform:translateY(6px)}to{opacity:1;transform:translateY(0)}}@keyframes fi{from{opacity:0}to{opacity:1}}@keyframes si{from{opacity:0;transform:scale(.97)}to{opacity:1;transform:scale(1)}}@keyframes po{0%{transform:scale(1)}50%{transform:scale(1.25)}100%{transform:scale(1)}}.tb{-webkit-tap-highlight-color:transparent;touch-action:manipulation}.tb:active{opacity:.7;transform:scale(.97)}.cl{transition:border-color .2s,box-shadow .15s}@media(min-width:768px){.mh{display:none!important}.dh{display:flex!important}.bb{display:none!important}.fw{padding-bottom:0!important;max-width:680px;margin:0 auto}.fs{display:grid!important;grid-template-columns:1fr 300px;gap:24px;max-width:1020px;margin:0 auto;align-items:start}.sd{display:flex!important}.cl:hover{border-color:${T.bdrA};box-shadow:${T.sh};transform:translateY(-1px)}}@media(max-width:767px){.dh{display:none!important}.sd{display:none!important}.fs{display:block!important}}@media(max-width:767px){.fw{padding-bottom:calc(60px + env(safe-area-inset-bottom))!important}}@media(display-mode:standalone){.mh{padding-top:env(safe-area-inset-top)!important;height:calc(52px + env(safe-area-inset-top))!important}}`;

// ─── PRIMITIVES ──────────────────────────────────────────────
function Av({T,i,ink=0,s=34}){const t=gT(ink);return <div style={{width:s,height:s,borderRadius:"50%",background:`linear-gradient(145deg,${t.c}20,${T.bg2})`,border:`1.5px solid ${t.c}28`,display:"flex",alignItems:"center",justifyContent:"center",fontFamily:T.ui,fontSize:s*.34,fontWeight:700,color:t.c,flexShrink:0}}>{i}</div>;}
function IB({T,ink,compact}){const t=gT(ink);return <span style={{display:"inline-flex",alignItems:"center",gap:3,padding:compact?"1px 5px":"2px 7px",borderRadius:4,fontSize:compact?9:10,fontWeight:600,fontFamily:T.ui,color:t.c,background:`${t.c}0D`}}>{compact?fN(ink):`${fN(ink)} · ${t.name}`}</span>;}
function LB({T,lens,compact}){const l=LN[lens];if(!l)return null;return <span style={{display:"inline-flex",alignItems:"center",gap:2,padding:"1px 6px",borderRadius:4,fontSize:9,fontWeight:500,fontFamily:T.ui,color:l.c,background:`${l.c}08`}}>{l.icon}{!compact&&` ${l.label}`}</span>;}
function TT({T,type}){const t=PT[type];if(!t)return null;const c=T[t.ck]||T.gold;return <span style={{display:"inline-flex",alignItems:"center",gap:3,padding:"2px 8px",borderRadius:4,fontSize:9,fontWeight:700,fontFamily:T.ui,color:c,background:`${c}0D`,letterSpacing:".04em",textTransform:"uppercase"}}>{t.icon} {t.label}</span>;}
function EB({T,icon,count,active,ac,onClick}){const[p,sP]=useState(false);return <button className="tb" onClick={()=>{onClick?.();sP(true);setTimeout(()=>sP(false),300);}} style={{display:"flex",alignItems:"center",gap:4,padding:"8px 10px",borderRadius:8,background:active?`${ac}0D`:"transparent",border:"none",cursor:"pointer",animation:p?"po .3s ease":"none",minHeight:40}}><span style={{display:"flex",alignItems:"center",color:active?ac:T.tx4}}>{icon}</span><span style={{fontFamily:T.ui,fontSize:11,fontWeight:600,color:active?ac:T.tx4,fontVariantNumeric:"tabular-nums"}}>{fN(count)}</span></button>;}
function Sec({T,title,sub,children,action}){return <section style={{marginBottom:24}}><div style={{display:"flex",alignItems:"center",justifyContent:"space-between",marginBottom:10}}><div><div style={{fontFamily:T.hd,fontSize:17,fontWeight:600,color:T.tx}}>{title}</div>{sub&&<div style={{fontFamily:T.bd,fontSize:11,color:T.tx3,fontStyle:"italic",marginTop:1}}>{sub}</div>}</div>{action}</div>{children}</section>;}
function Card({T,children,pad="16px",mb=0}){return <div className="cl" style={{background:T.sf,borderRadius:14,border:`1px solid ${T.bdr}`,padding:pad,marginBottom:mb}}>{children}</div>;}
function Empty({T,icon,title,sub}){return <div style={{textAlign:"center",padding:"48px 16px",animation:"fi .3s ease"}}><div style={{fontSize:36,marginBottom:10,opacity:.15}}>{icon}</div><div style={{fontFamily:T.hd,fontSize:18,fontWeight:600,color:T.tx,marginBottom:6}}>{title}</div><p style={{fontFamily:T.bd,fontSize:13,color:T.tx3}}>{sub}</p></div>;}

// ─── FEED CARD ───────────────────────────────────────────────
function FC({T,item,onToggle,onBook,onUser,index=0}){const[so,setSo]=useState(false);const[mo,setMo]=useState(false);
const content=<>{item.title&&<h3 style={{fontFamily:T.hd,fontSize:19,fontWeight:600,color:T.tx,lineHeight:1.3,marginBottom:6}}>{item.title}</h3>}<div style={{fontFamily:T.bd,fontSize:14.5,lineHeight:1.7,color:T.tx2,fontWeight:300,whiteSpace:"pre-line"}}>{item.text}</div></>;
return <article className="cl" style={{background:T.sf,borderRadius:14,border:`1px solid ${T.bdr}`,padding:"18px 16px 12px",animation:`en .35s ease ${index*.05}s both`}}>
<div style={{display:"flex",alignItems:"flex-start",gap:10,marginBottom:12}}><div onClick={()=>onUser?.(item.user)} style={{cursor:"pointer",flexShrink:0}}><Av T={T} i={item.user.in} ink={item.user.ink} s={38}/></div><div style={{flex:1,minWidth:0}}><div style={{display:"flex",alignItems:"center",gap:5,flexWrap:"wrap"}}><span onClick={()=>onUser?.(item.user)} style={{fontFamily:T.ui,fontSize:13.5,fontWeight:650,color:T.tx,cursor:"pointer"}}>{item.user.name}</span>{item.attestation&&<span style={{fontSize:8,padding:"1px 5px",borderRadius:3,background:`${T.gn}0D`,color:T.gn,fontFamily:T.ui,fontWeight:700}}>✓ HUMAN</span>}{item.isFirst&&<span style={{fontSize:8,padding:"1px 5px",borderRadius:3,background:`${T.gold}0D`,color:T.gold,fontFamily:T.ui,fontWeight:700}}>✦ FIRST</span>}</div><div style={{display:"flex",alignItems:"center",gap:5,marginTop:2,flexWrap:"wrap"}}><span style={{fontFamily:T.ui,fontSize:11,color:T.tx4}}>{item.user.h}</span><span style={{color:T.tx4,fontSize:8}}>·</span><span style={{fontFamily:T.ui,fontSize:11,color:T.tx4}}>{item.time}</span><IB T={T} ink={item.user.ink} compact/><LB T={T} lens={item.user.lens} compact/></div></div><div style={{display:"flex",alignItems:"center",gap:6,flexShrink:0}}><TT T={T} type={item.type}/><div style={{position:"relative"}}><button className="tb" onClick={()=>setMo(!mo)} style={{background:"none",border:"none",cursor:"pointer",padding:8,fontSize:18,color:T.tx4,minWidth:36,minHeight:36,display:"flex",alignItems:"center",justifyContent:"center"}}>⋮</button>{mo&&<div onClick={()=>setMo(false)} style={{position:"absolute",top:"100%",right:0,background:T.sf,border:`1px solid ${T.bdrA}`,borderRadius:12,padding:6,minWidth:160,boxShadow:T.shL,zIndex:50,animation:"si .12s ease"}}>{["Hide post","Mute author","Report"].map(a=><button key={a} className="tb" style={{display:"block",width:"100%",padding:"12px 14px",borderRadius:8,border:"none",background:"none",fontFamily:T.ui,fontSize:13,color:a==="Report"?T.rd:T.tx2,cursor:"pointer",textAlign:"left",minHeight:44}}>{a}</button>)}</div>}</div></div></div>
{item.bookRef&&<div onClick={()=>onBook?.(item.bookRef.title,item.bookRef.author)} className="tb" style={{display:"flex",alignItems:"center",gap:10,padding:"8px 12px",borderRadius:8,background:T.bg2,border:`1px solid ${T.bdr}`,marginBottom:10,cursor:"pointer"}}><div style={{width:26,height:38,borderRadius:3,flexShrink:0,background:`linear-gradient(140deg,${item.bookRef.cc||T.acc}90,${item.bookRef.cc||T.acc}50)`}}/><div style={{flex:1,minWidth:0}}><div style={{fontFamily:T.ui,fontSize:12,fontWeight:600,color:T.tx}}>{item.bookRef.title}</div><div style={{fontFamily:T.ui,fontSize:10,color:T.tx3}}>{item.bookRef.author}</div></div>{item.rating&&<div style={{fontFamily:T.ui,fontSize:11,color:T.gold}}>{"★".repeat(item.rating)}<span style={{color:T.tx4}}>{"★".repeat(5-item.rating)}</span></div>}</div>}
{item.inspiredBy&&<div style={{display:"flex",alignItems:"center",gap:5,padding:"6px 10px",borderRadius:6,background:`${T.pl}06`,border:`1px solid ${T.pl}0D`,marginBottom:10,fontFamily:T.ui,fontSize:10.5,color:T.pl}}>◇ Inspired by <strong>{item.inspiredBy.title}</strong> — {item.inspiredBy.author}</div>}
{item.type==="spoiler"&&!so?<div style={{padding:"24px 16px",borderRadius:10,textAlign:"center",background:`repeating-linear-gradient(135deg,${T.rd}05,${T.rd}05 2px,transparent 2px,transparent 8px)`,border:`1px dashed ${T.rd}20`}}><div style={{fontFamily:T.ui,fontSize:10,fontWeight:700,color:T.rd,letterSpacing:".08em",textTransform:"uppercase",marginBottom:4}}>⚠ Spoiler Zone</div><div style={{fontFamily:T.bd,fontSize:12,color:T.tx3,marginBottom:14}}>{item.bookRef?.title}{item.spoilerPage?` · ${item.spoilerPage}`:""}</div><button className="tb" onClick={()=>setSo(true)} style={{padding:"10px 24px",borderRadius:8,background:`${T.rd}0D`,border:`1px solid ${T.rd}20`,fontFamily:T.ui,fontSize:12,fontWeight:600,color:T.rd,cursor:"pointer",minHeight:44}}>Reveal Content</button></div>:content}
{item.tags?.length>0&&<div style={{display:"flex",gap:4,flexWrap:"wrap",marginTop:10}}>{item.tags.map(t=><span key={t} style={{padding:"2px 8px",borderRadius:4,fontSize:10,fontFamily:T.ui,fontWeight:500,color:T.tx3,background:T.bg2,border:`1px solid ${T.bdr}`}}>{t}</span>)}</div>}
<div style={{display:"flex",alignItems:"center",gap:0,marginTop:12,paddingTop:10,borderTop:`1px solid ${T.bdr}`,marginLeft:-4,marginRight:-4}}><EB T={T} icon="♡" count={item.likes} active={item.isLiked} ac={T.rd} onClick={()=>onToggle(item.id,"like")}/><EB T={T} icon={<Reply size={15}/>} count={item.comments} active={false} ac={T.bl}/><EB T={T} icon="⊞" count={item.shelved} active={item.isShelved} ac={T.gold} onClick={()=>onToggle(item.id,"shelf")}/><EB T={T} icon="⤴" count={item.reposts} active={item.isReposted} ac={T.gn} onClick={()=>onToggle(item.id,"repost")}/><div style={{flex:1}}/><button className="tb" style={{background:"none",border:"none",cursor:"pointer",fontFamily:T.ui,fontSize:11,color:T.tx4,padding:"8px 6px",minHeight:40}}>⎘</button></div>
</article>;}

// ─── FEED SCREEN ─────────────────────────────────────────────
function FeedScreen({T,feed,onToggle,onBook,onUser,searchQ,loadMore,feedLoading,hasMoreFeed}){
const[filter,setFilter]=useState("foryou");const[pi,setPi]=useState(0);
const FL=[{id:"foryou",l:"✦ For You"},{id:"all",l:"All"},{id:"original",l:"✎ Original"},{id:"review",l:"◈ Reviews"},{id:"recommendation",l:"⬨ Recs"},{id:"spoiler",l:"⚠ Spoiler"}];
const filtered=filter==="foryou"?feed.filter(f=>f.following||f.lensMatch):filter==="all"?feed:feed.filter(f=>f.type===filter);
const searched=searchQ.trim()?filtered.filter(f=>{const q=searchQ.toLowerCase();return(f.title||"").toLowerCase().includes(q)||(f.text||"").toLowerCase().includes(q)||f.user.name.toLowerCase().includes(q)||(f.bookRef?.title||"").toLowerCase().includes(q);}):filtered;
return <>
<div style={{marginBottom:16}}><div style={{fontFamily:T.ui,fontSize:10,fontWeight:700,color:T.tx4,letterSpacing:".1em",textTransform:"uppercase",marginBottom:8}}>Currently Reading</div><div style={{display:"flex",gap:8,overflowX:"auto",WebkitOverflowScrolling:"touch",scrollSnapType:"x mandatory",scrollbarWidth:"none"}}>{CR.map((cr,i)=><div key={i} onClick={()=>onBook?.(cr.book,cr.author)} className="tb" style={{flex:"0 0 auto",scrollSnapAlign:"start",display:"flex",alignItems:"center",gap:10,padding:"10px 14px",borderRadius:12,background:T.sf,border:`1px solid ${T.bdr}`,minWidth:180,maxWidth:220,cursor:"pointer"}}><Av T={T} i={cr.user.in} ink={cr.user.ink} s={28}/><div style={{flex:1,minWidth:0}}><div style={{fontFamily:T.ui,fontSize:11.5,fontWeight:600,color:T.tx,overflow:"hidden",textOverflow:"ellipsis",whiteSpace:"nowrap"}}>{cr.book}</div><div style={{fontFamily:T.ui,fontSize:10,color:T.tx4}}>{cr.author}</div></div><div style={{width:30,height:30,borderRadius:"50%",flexShrink:0,background:`conic-gradient(${T.acc} ${cr.prog}%,${T.bdr} ${cr.prog}%)`,display:"flex",alignItems:"center",justifyContent:"center"}}><div style={{width:24,height:24,borderRadius:"50%",background:T.sf,display:"flex",alignItems:"center",justifyContent:"center",fontFamily:T.mn,fontSize:8,fontWeight:500,color:T.tx3}}>{cr.prog}</div></div></div>)}</div></div>
<div style={{display:"flex",gap:6,overflowX:"auto",WebkitOverflowScrolling:"touch",marginBottom:14,scrollbarWidth:"none"}}>{FL.map(f=><button key={f.id} className="tb" onClick={()=>setFilter(f.id)} style={{padding:"8px 16px",borderRadius:20,border:`1px solid ${filter===f.id?T.bdrA:T.bdr}`,fontFamily:T.ui,fontSize:12,fontWeight:filter===f.id?700:500,cursor:"pointer",whiteSpace:"nowrap",minHeight:38,background:filter===f.id?T.gs:"transparent",color:filter===f.id?T.gold:T.tx3}}>{f.l}</button>)}</div>
{searchQ&&<div style={{fontFamily:T.ui,fontSize:12,color:T.tx3,marginBottom:12}}>⌕ "{searchQ}" · {searched.length} found</div>}
<Card T={T} pad="16px 16px 14px" mb={14}><div style={{fontFamily:T.ui,fontSize:9,fontWeight:700,color:T.acc,letterSpacing:".1em",textTransform:"uppercase",marginBottom:8}}>✎ Writing Prompt</div><div style={{fontFamily:T.hd,fontSize:16,fontWeight:500,color:T.tx,lineHeight:1.45,fontStyle:"italic",marginBottom:12}}>"{PRM[pi]}"</div><div style={{display:"flex",gap:8}}><button className="tb" style={{flex:1,padding:"10px 0",borderRadius:8,border:"none",background:T.acc,color:"#fff",fontFamily:T.ui,fontSize:12,fontWeight:700,cursor:"pointer",minHeight:44,boxShadow:`0 2px 8px ${T.acc}30`}}>Write This</button><button className="tb" onClick={()=>setPi((pi+1)%PRM.length)} style={{padding:"10px 18px",borderRadius:8,border:`1px solid ${T.bdr}`,background:"none",color:T.tx3,fontFamily:T.ui,fontSize:12,fontWeight:600,cursor:"pointer",minHeight:44}}>Next</button></div></Card>
<div style={{display:"flex",flexDirection:"column",gap:10}}>{searched.length===0?<Empty T={T} icon="⌕" title={searchQ?`Nothing for "${searchQ}"`:"No posts here yet"} sub={searchQ?"Try different keywords.":"Be the first to write one."}/>:searched.map((item,i)=><FC key={item.id} T={T} item={item} onToggle={onToggle} onBook={onBook} onUser={onUser} index={i}/>)}</div>
<div style={{marginTop:16}}><Card T={T} pad="16px 16px 8px"><div style={{fontFamily:T.hd,fontSize:16,fontWeight:600,color:T.tx,marginBottom:12}}>Trending Now</div>{TRD.map((b,i)=><div key={i} className="tb" style={{display:"flex",alignItems:"center",gap:10,padding:"10px 4px",cursor:"pointer",borderBottom:i<TRD.length-1?`1px solid ${T.bdr}`:"none",minHeight:48}}><div style={{fontFamily:T.mn,fontSize:11,fontWeight:500,color:T.tx4,width:18,textAlign:"center"}}>{i+1}</div><div style={{width:22,height:32,borderRadius:3,flexShrink:0,background:`linear-gradient(140deg,${b.c}AA,${b.c}60)`}}/><div style={{flex:1,minWidth:0}}><div style={{fontFamily:T.ui,fontSize:12,fontWeight:600,color:T.tx}}>{b.title}</div><div style={{fontFamily:T.ui,fontSize:10,color:T.tx3}}>{b.author}</div></div><span style={{fontFamily:T.mn,fontSize:10,fontWeight:500,color:T.gn,background:`${T.gn}0D`,padding:"2px 6px",borderRadius:3}}>{b.heat}</span></div>)}</Card></div>
{searched.length>0&&<div style={{textAlign:"center",padding:"40px 16px 24px",borderTop:`1px solid ${T.bdr}`,marginTop:16}}><div style={{fontFamily:T.hd,fontSize:20,fontWeight:600,color:T.tx,fontStyle:"italic",marginBottom:6}}>You're caught up.</div><p style={{fontFamily:T.bd,fontSize:13,color:T.tx3,lineHeight:1.6,maxWidth:340,margin:"0 auto 16px"}}>Everything new has been read. The page is yours.</p></div>}
{/* Load more posts button for infinite scroll */}
{hasMoreFeed&&searched.length>0&&<div style={{textAlign:"center",padding:"16px 0 8px"}}><button className="tb" disabled={feedLoading} onClick={()=>loadMore&&loadMore()} style={{padding:"10px 24px",borderRadius:10,border:`1px solid ${T.bdr}`,background:T.bg2,fontFamily:T.ui,fontSize:12,fontWeight:600,color:feedLoading?T.tx4:T.tx,cursor:feedLoading?"default":"pointer"}}>{feedLoading?"Loading…":"Load more"}</button></div>}
</>;}

// ─── EXPLORE SCREEN ──────────────────────────────────────────
function ExploreScreen({T,onBook,defaultSection="discover"}){
const[section,setSection]=useState(defaultSection);
const[following,setFl]=useState({});const[lf,setLf]=useState("all");
const[bookQ,setBookQ]=useState("");const[genre,setGenre]=useState("All");
const[pressTab,setPT]=useState("discover");const[form,setForm]=useState("all");
const readers=[...US].map((u,i)=>({...u,distance:["0.8 mi","1.2 mi","2.1 mi","3.4 mi","4.7 mi","6.2 mi","8.1 mi","12 mi"][i],currentBook:CR[i%CR.length]?.book||"Beloved",bio:["Reading as an act of feeling.","Structure is story.","Every sentence is a door.","What question does this book refuse to answer?","Borders are for crossing.","Prose should leave marks.","Language is the house of being.","Two threads. One needle."][i]}));
const filteredReaders=lf==="all"?readers:readers.filter(u=>u.lens===lf);
const allBooks=Object.values(BOOK_DATA);
const allGenres=["All",...new Set(allBooks.flatMap(b=>b.genres||[]))].slice(0,9);
const bookResults=(bookQ.trim()?allBooks.filter(b=>(b.title||"").toLowerCase().includes(bookQ.toLowerCase())||(b.author||"").toLowerCase().includes(bookQ.toLowerCase())):allBooks).filter(b=>genre==="All"||(b.genres||[]).includes(genre));
const FF=[{id:"all",l:"All"},{id:"flash",l:"Flash"},{id:"fiction",l:"Fiction"},{id:"essay",l:"Essay"},{id:"poetry",l:"Poetry"}];
const pressFiltered=form==="all"?PRESS_WORKS:form==="poetry"?PRESS_WORKS.filter(w=>w.form==="poetry"):form==="flash"?PRESS_WORKS.filter(w=>w.words<1000&&w.form!=="poetry"):PRESS_WORKS.filter(w=>w.form===form);
const SECS=[{id:"discover",l:"Discover"},{id:"books",l:"Books"},{id:"press",l:"Press"}];
return <div style={{animation:"en .35s ease both"}}>
<div style={{display:"flex",gap:0,marginBottom:20,borderBottom:`1px solid ${T.bdr}`}}>
{SECS.map(s=><button key={s.id} className="tb" onClick={()=>setSection(s.id)} style={{padding:"10px 18px",border:"none",cursor:"pointer",fontFamily:T.ui,fontSize:13,fontWeight:section===s.id?700:500,background:"transparent",color:section===s.id?T.tx:T.tx3,borderBottom:section===s.id?`2px solid ${T.acc}`:"2px solid transparent"}}>{s.l}</button>)}
</div>

{section==="discover"&&<>
<Sec T={T} title={<><BookOpen size={13} style={{verticalAlign:"middle",marginRight:4}}/>Reading Right Now</>} sub="Live">
<div style={{display:"flex",gap:8,overflowX:"auto",WebkitOverflowScrolling:"touch",scrollbarWidth:"none"}}>
{CR.slice(0,3).map((cr,i)=><div key={i} onClick={()=>onBook?.(cr.book,cr.author)} className="tb" style={{cursor:"pointer",flex:"0 0 auto",scrollSnapAlign:"start"}}>
<Card T={T} pad="14px 16px"><div style={{display:"flex",alignItems:"center",gap:10,minWidth:160}}>
<div style={{width:28,height:42,borderRadius:"1px 3px 3px 1px",background:`linear-gradient(145deg,${T.acc}CC,#6B2A10)`,boxShadow:"2px 0 6px rgba(0,0,0,.3)",flexShrink:0}}/>
<div><div style={{fontFamily:T.hd,fontSize:14,fontWeight:700,color:T.tx}}>{cr.book}</div><div style={{fontFamily:T.bd,fontSize:11,color:T.tx3,fontStyle:"italic"}}>{cr.author}</div></div>
</div></Card></div>)}
</div></Sec>
<Sec T={T} title={<><MapPin size={13} style={{verticalAlign:"middle",marginRight:4}}/>Readers Near You</>}>
<div style={{display:"flex",gap:5,overflowX:"auto",marginBottom:12,scrollbarWidth:"none"}}>
<button className="tb" onClick={()=>setLf("all")} style={{padding:"5px 12px",borderRadius:7,border:`1px solid ${lf==="all"?`${T.gold}25`:T.bdr}`,background:lf==="all"?T.gs:"transparent",fontFamily:T.ui,fontSize:10,fontWeight:lf==="all"?700:500,color:lf==="all"?T.gold:T.tx4,cursor:"pointer",whiteSpace:"nowrap"}}>All</button>
{Object.entries(LN).map(([k,v])=><button key={k} className="tb" onClick={()=>setLf(k)} style={{padding:"5px 12px",borderRadius:7,border:`1px solid ${lf===k?`${v.c}25`:T.bdr}`,background:lf===k?`${v.c}08`:"transparent",fontFamily:T.ui,fontSize:10,fontWeight:lf===k?700:500,color:lf===k?v.c:T.tx4,cursor:"pointer",whiteSpace:"nowrap"}}>{v.icon} {v.label}</button>)}
</div>
<div style={{display:"flex",flexDirection:"column",gap:8}}>
{filteredReaders.map(u=>{const isF=following[u.id];return <Card key={u.id} T={T} pad="14px 16px">
<div style={{display:"flex",alignItems:"center",gap:10}}>
<Av T={T} i={u.in} ink={u.ink} s={40}/>
<div style={{flex:1,minWidth:0}}>
<div style={{display:"flex",alignItems:"center",gap:5,flexWrap:"wrap"}}><span style={{fontFamily:T.ui,fontSize:12,fontWeight:700,color:T.tx}}>{u.name}</span><LB T={T} lens={u.lens} compact/><span style={{fontFamily:T.ui,fontSize:9,color:T.tx4,display:"inline-flex",alignItems:"center",gap:2}}><MapPin size={9}/>{u.distance}</span></div>
<div style={{fontFamily:T.bd,fontSize:11,color:T.tx3,fontStyle:"italic",marginTop:1}}>{u.bio}</div>
<div style={{fontFamily:T.ui,fontSize:10,color:T.tx4,marginTop:4}}>Reading: <strong style={{color:T.tx2}}>{u.currentBook}</strong></div>
</div>
<button className="tb" onClick={()=>setFl(p=>({...p,[u.id]:!p[u.id]}))} style={{padding:"8px 14px",borderRadius:8,border:`1px solid ${isF?`${T.gn}25`:T.bdr}`,background:isF?`${T.gn}06`:"transparent",fontFamily:T.ui,fontSize:11,fontWeight:700,color:isF?T.gn:T.tx3,cursor:"pointer",flexShrink:0,minHeight:40}}>{isF?"✓ Following":"Follow"}</button>
</div></Card>;})}
</div></Sec>
<Sec T={T} title={<><Flame size={13} style={{verticalAlign:"middle",marginRight:4}}/>Trending This Week</>}>
<div style={{display:"grid",gridTemplateColumns:"1fr 1fr",gap:8}}>
{TRD.map((b,i)=><div key={i} onClick={()=>onBook?.(b.title,b.author)} className="tb" style={{cursor:"pointer"}}>
<Card T={T} pad="14px"><div style={{width:38,height:56,borderRadius:"1px 4px 4px 1px",background:`linear-gradient(145deg,${b.c}CC,${b.c}60)`,boxShadow:"2px 0 6px rgba(0,0,0,.3)",marginBottom:10}}/><div style={{fontFamily:T.hd,fontSize:13,fontWeight:700,color:T.tx,lineHeight:1.2,marginBottom:2}}>{b.title}</div><div style={{fontFamily:T.bd,fontSize:10,color:T.tx3,fontStyle:"italic",marginBottom:4}}>{b.author}</div><div style={{display:"flex",gap:6,fontFamily:T.ui,fontSize:9,color:T.tx4}}><span>{b.readers} readers</span><span style={{color:T.gn,fontWeight:700}}>{b.heat}</span></div></Card>
</div>)}
</div></Sec>
</>}

{section==="books"&&<>
<div style={{position:"relative",marginBottom:12}}>
<input value={bookQ} onChange={e=>setBookQ(e.target.value)} placeholder="Search by title or author…" style={{width:"100%",padding:"12px 14px 12px 40px",borderRadius:12,background:T.bg2,border:`1px solid ${bookQ?T.bdrA:T.bdr}`,fontFamily:T.ui,fontSize:13,color:T.tx,outline:"none"}}/>
<span style={{position:"absolute",left:13,top:"50%",transform:"translateY(-50%)",fontSize:16,color:T.tx4,pointerEvents:"none"}}>⌕</span>
{bookQ&&<button className="tb" onClick={()=>setBookQ("")} style={{position:"absolute",right:10,top:"50%",transform:"translateY(-50%)",background:"none",border:"none",color:T.tx4,cursor:"pointer",fontSize:14,padding:4}}>✕</button>}
</div>
<div style={{display:"flex",gap:5,overflowX:"auto",scrollbarWidth:"none",marginBottom:16}}>
{allGenres.map(g=><button key={g} className="tb" onClick={()=>setGenre(g)} style={{padding:"5px 13px",borderRadius:20,border:`1px solid ${genre===g?`${T.acc}25`:T.bdr}`,background:genre===g?`${T.acc}0D`:"transparent",fontFamily:T.ui,fontSize:10,fontWeight:genre===g?700:500,color:genre===g?T.acc:T.tx4,cursor:"pointer",whiteSpace:"nowrap"}}>{g}</button>)}
</div>
{bookResults.length===0&&<div style={{textAlign:"center",padding:"40px 16px",fontFamily:T.bd,fontSize:14,color:T.tx3,fontStyle:"italic"}}>No books found for "{bookQ}"</div>}
<div style={{display:"grid",gridTemplateColumns:"1fr 1fr",gap:12}}>
{bookResults.map((b,i)=><button key={i} className="tb" onClick={()=>onBook?.(b.title,b.author)} style={{display:"flex",flexDirection:"column",padding:"0 0 12px",borderRadius:14,background:T.sf,border:`1px solid ${T.bdr}`,cursor:"pointer",textAlign:"left",width:"100%",overflow:"hidden"}}>
<div style={{width:"100%",paddingTop:"130%",position:"relative",background:`linear-gradient(145deg,${b.cc||T.acc}CC,${b.cc||T.acc}55)`,marginBottom:10}}>
<div style={{position:"absolute",inset:0,background:"linear-gradient(to bottom,transparent 40%,rgba(0,0,0,.5))",display:"flex",flexDirection:"column",justifyContent:"flex-end",padding:"10px 10px"}}>
<div style={{fontFamily:T.hd,fontSize:13,fontWeight:700,color:"#fff",lineHeight:1.2}}>{b.title}</div>
</div>
</div>
<div style={{padding:"0 10px"}}>
<div style={{fontFamily:T.bd,fontSize:10,color:T.tx3,fontStyle:"italic",marginBottom:5}}>{b.author}</div>
<div style={{display:"flex",alignItems:"center",justifyContent:"space-between"}}>
<div style={{display:"flex",gap:1}}>{[1,2,3,4,5].map(s=><span key={s} style={{fontSize:9,color:s<=Math.round(b.rating||0)?T.gold:T.tx4}}>★</span>)}</div>
<span style={{fontFamily:T.mn,fontSize:9,color:T.tx4}}>{b.year}</span>
</div>
</div>
</button>)}
</div>
</>}

{section==="press"&&<>
<div style={{marginBottom:16}}><h2 style={{fontFamily:T.hd,fontSize:22,fontWeight:700,color:T.tx,letterSpacing:"-.02em"}}>The Press</h2><p style={{fontFamily:T.bd,fontSize:12,color:T.tx3,fontStyle:"italic",marginTop:2}}>Original work — fiction, poetry, essays, and everything between.</p></div>
<div style={{display:"flex",gap:0,marginBottom:16,borderBottom:`1px solid ${T.bdr}`}}>{["discover","picks","trending"].map(t=><button key={t} className="tb" onClick={()=>setPT(t)} style={{padding:"10px 16px",border:"none",cursor:"pointer",fontFamily:T.ui,fontSize:12,fontWeight:pressTab===t?700:500,background:"transparent",color:pressTab===t?T.tx:T.tx3,borderBottom:pressTab===t?`2px solid ${T.acc}`:"2px solid transparent"}}>{t==="discover"?"Discover":t==="picks"?"Editor's Picks":"Trending"}</button>)}</div>
{pressTab==="discover"&&<><div style={{display:"flex",gap:3,marginBottom:14,overflowX:"auto",scrollbarWidth:"none"}}>{FF.map(f=><button key={f.id} className="tb" onClick={()=>setForm(f.id)} style={{padding:"6px 14px",borderRadius:8,border:`1px solid ${form===f.id?`${T.acc}20`:T.bdr}`,background:form===f.id?`${T.acc}0D`:"transparent",fontFamily:T.ui,fontSize:10,fontWeight:form===f.id?700:500,color:form===f.id?T.acc:T.tx3,cursor:"pointer",whiteSpace:"nowrap"}}>{f.l}</button>)}</div>
<div style={{display:"flex",flexDirection:"column",gap:12}}>{pressFiltered.map(w=><Card key={w.id} T={T} pad="18px 16px">
<div style={{display:"flex",alignItems:"center",gap:8,marginBottom:10}}><Av T={T} i={w.author.in} ink={w.author.ink} s={32}/><div style={{flex:1}}><div style={{display:"flex",alignItems:"center",gap:5}}><span style={{fontFamily:T.ui,fontSize:12,fontWeight:700,color:T.tx}}>{w.author.name}</span><IB T={T} ink={w.author.ink} compact/></div><div style={{fontFamily:T.ui,fontSize:10,color:T.tx4}}>{w.readTime} min · {w.form}</div></div>{w.attested&&<span style={{fontSize:8,padding:"1px 5px",borderRadius:3,background:`${T.gn}0D`,color:T.gn,fontFamily:T.ui,fontWeight:700}}>✓ HUMAN</span>}</div>
<h3 style={{fontFamily:T.hd,fontSize:18,fontWeight:700,color:T.tx,fontStyle:"italic",lineHeight:1.3,marginBottom:8}}>{w.title}</h3>
{w.tags?.length>0&&<div style={{display:"flex",gap:3,flexWrap:"wrap",marginBottom:8}}>{w.tags.map(t=><span key={t} style={{padding:"2px 7px",borderRadius:4,fontSize:8,fontWeight:600,fontFamily:T.ui,background:`${T.acc}08`,color:T.acc}}>{t}</span>)}{w.moods?.map(t=><span key={t} style={{padding:"2px 7px",borderRadius:4,fontSize:8,fontFamily:T.ui,background:`${T.gold}06`,color:T.gold,fontStyle:"italic"}}>{t}</span>)}</div>}
<div style={{fontFamily:w.form==="poetry"?T.hd:T.bd,fontSize:w.form==="poetry"?14:13.5,lineHeight:w.form==="poetry"?1.9:1.7,color:T.tx2,fontWeight:w.form==="poetry"?400:300,whiteSpace:"pre-wrap",marginBottom:10}}>{w.excerpt.length>250?w.excerpt.slice(0,250)+"…":w.excerpt}</div>
{w.featured&&w.note&&<div style={{padding:"8px 12px",borderRadius:8,background:`${T.gold}04`,border:`1px solid ${T.gold}08`,marginBottom:8}}><div style={{fontFamily:T.bd,fontSize:10.5,color:T.gold,fontStyle:"italic",display:"flex",alignItems:"center",gap:4}}><Palette size={10}/>{w.note}</div></div>}
<div style={{display:"flex",alignItems:"center",gap:10,fontFamily:T.ui,fontSize:10,color:T.tx4}}><span>{w.words.toLocaleString()} words</span><span style={{opacity:.3}}>·</span><span>♡ {w.likes}</span><span style={{display:"inline-flex",alignItems:"center",gap:2}}><MessageCircle size={9}/>{w.comments}</span><span>◆ {w.shelved}</span></div>
</Card>)}</div></>}
{pressTab==="picks"&&<div style={{display:"flex",flexDirection:"column",gap:12}}><Card T={T} pad="16px"><div style={{fontFamily:T.hd,fontSize:16,fontWeight:700,color:T.gold,marginBottom:4,display:"flex",alignItems:"center",gap:5}}><Palette size={14}/>Editor's Picks</div><div style={{fontFamily:T.bd,fontSize:11,color:T.tx3,fontStyle:"italic",lineHeight:1.6}}>Work that embodies what Précis is for — writing that earns its place on the page.</div></Card>{PRESS_WORKS.filter(w=>w.featured).map(w=><Card key={w.id} T={T} pad="16px"><h3 style={{fontFamily:T.hd,fontSize:16,fontWeight:700,color:T.tx,fontStyle:"italic",marginBottom:4}}>{w.title}</h3><div style={{fontFamily:T.ui,fontSize:10,color:T.tx3,marginBottom:6}}>{w.author.name} · {w.form} · {w.readTime} min</div>{w.note&&<div style={{fontFamily:T.bd,fontSize:11,color:T.gold,fontStyle:"italic",display:"flex",alignItems:"center",gap:4}}><Palette size={10}/>{w.note}</div>}</Card>)}</div>}
{pressTab==="trending"&&<div style={{display:"flex",flexDirection:"column",gap:10}}>{[...PRESS_WORKS].sort((a,b)=>(b.likes+b.shelved)-(a.likes+a.shelved)).map((w,i)=><div key={w.id} style={{display:"flex",alignItems:"flex-start",gap:10}}><div style={{fontFamily:T.hd,fontSize:22,fontWeight:700,color:`${T.gold}30`,width:28,textAlign:"right",flexShrink:0,marginTop:4}}>{i+1}</div><Card T={T} pad="14px 16px"><h3 style={{fontFamily:T.hd,fontSize:15,fontWeight:700,color:T.tx,fontStyle:"italic",marginBottom:2}}>{w.title}</h3><div style={{fontFamily:T.ui,fontSize:10,color:T.tx3}}>{w.author.name} · ♡ {w.likes} · ◆ {w.shelved}</div></Card></div>)}</div>}
</>}
</div>;}

// ─── SHELF SCREEN ────────────────────────────────────────────
function ShelfScreen({T,onBook}){
const[tab,setTab]=useState("shelved");const[bookFilter,setBf]=useState("all");
const BF=[{id:"all",l:"All"},{id:"reading",l:<><BookOpen size={11} style={{verticalAlign:"middle",marginRight:3}}/>Reading</>},{id:"read",l:"✓ Read"},{id:"want",l:"◇ Want"}];
const filteredBooks=bookFilter==="all"?MY_BOOKS:MY_BOOKS.filter(b=>b.status===bookFilter);
return <div style={{animation:"en .35s ease both"}}>
<div style={{marginBottom:16}}><h2 style={{fontFamily:T.hd,fontSize:22,fontWeight:700,color:T.tx}}>My Shelf</h2><div style={{display:"flex",gap:12,marginTop:6,fontFamily:T.ui,fontSize:11,color:T.tx3}}><span>{MY_BOOKS.length} books</span><span>·</span><span>{SHELF_ITEMS.length} shelved posts</span></div></div>
<div style={{display:"flex",gap:0,marginBottom:16,borderBottom:`1px solid ${T.bdr}`}}>{[{id:"shelved",l:"Shelved Posts"},{id:"library",l:"Library"},{id:"waypoints",l:"Waypoints"}].map(t=><button key={t.id} className="tb" onClick={()=>setTab(t.id)} style={{padding:"10px 16px",border:"none",cursor:"pointer",fontFamily:T.ui,fontSize:12,fontWeight:tab===t.id?700:500,background:"transparent",color:tab===t.id?T.tx:T.tx3,borderBottom:tab===t.id?`2px solid ${T.acc}`:"2px solid transparent"}}>{t.l}</button>)}</div>
{tab==="shelved"&&<div style={{display:"flex",flexDirection:"column",gap:8}}>{SHELF_ITEMS.map(s=><Card key={s.id} T={T} pad="14px 16px"><div style={{display:"flex",alignItems:"center",gap:6,marginBottom:6}}><TT T={T} type={s.type}/><span style={{fontFamily:T.ui,fontSize:10,color:T.tx4}}>Shelved {s.shelvedAt}</span></div>{s.title&&<div style={{fontFamily:T.hd,fontSize:15,fontWeight:600,color:T.tx,marginBottom:4}}>{s.title}</div>}{s.book&&<div style={{fontFamily:T.ui,fontSize:11,color:T.tx2,marginBottom:4}}>on <strong>{s.book.title}</strong> by {s.book.author}</div>}<div style={{fontFamily:T.bd,fontSize:12.5,lineHeight:1.6,color:T.tx3,fontWeight:300}}>{s.snippet}</div><div style={{fontFamily:T.ui,fontSize:10,color:T.tx4,marginTop:6}}>by {s.authorName} · <LB T={T} lens={s.lens} compact/></div></Card>)}</div>}
{tab==="library"&&<><div style={{display:"flex",gap:6,marginBottom:14,overflowX:"auto",scrollbarWidth:"none"}}>{BF.map(f=><button key={f.id} className="tb" onClick={()=>setBf(f.id)} style={{padding:"7px 14px",borderRadius:20,border:`1px solid ${bookFilter===f.id?T.bdrA:T.bdr}`,background:bookFilter===f.id?T.gs:"transparent",fontFamily:T.ui,fontSize:11,fontWeight:bookFilter===f.id?700:500,color:bookFilter===f.id?T.gold:T.tx3,cursor:"pointer",whiteSpace:"nowrap"}}>{f.l}</button>)}</div>
<div style={{display:"flex",flexDirection:"column",gap:8}}>{filteredBooks.map((b,i)=><div key={i} onClick={()=>onBook?.(b.title,b.author)} className="tb" style={{cursor:"pointer"}}><Card T={T} pad="14px 16px"><div style={{display:"flex",alignItems:"center",gap:10}}><div style={{width:28,height:42,borderRadius:3,background:`linear-gradient(145deg,${T.acc}CC,#6B2A10)`,boxShadow:"2px 0 6px rgba(0,0,0,.25)",flexShrink:0}}/><div style={{flex:1}}><div style={{fontFamily:T.hd,fontSize:14,fontWeight:700,color:T.tx}}>{b.title}</div><div style={{fontFamily:T.bd,fontSize:11,color:T.tx3,fontStyle:"italic"}}>{b.author}</div><div style={{display:"flex",alignItems:"center",gap:6,marginTop:3}}><span style={{fontFamily:T.ui,fontSize:9,padding:"2px 6px",borderRadius:4,background:b.status==="reading"?`${T.bl}0D`:b.status==="read"?`${T.gn}0D`:`${T.gold}0D`,color:b.status==="reading"?T.bl:b.status==="read"?T.gn:T.gold,fontWeight:600}}>{b.status==="reading"?<><BookOpen size={9} style={{verticalAlign:"middle",marginRight:2}}/>Reading</>:b.status==="read"?"✓ Read":"◇ Want"}</span>{b.rating&&<span style={{fontFamily:T.ui,fontSize:10,color:T.gold}}>{"★".repeat(b.rating)}</span>}{b.progress&&<span style={{fontFamily:T.mn,fontSize:9,color:T.acc}}>{b.progress}%</span>}</div></div></div></Card></div>)}</div></>}
{tab==="waypoints"&&<Empty T={T} icon="⟐" title="No waypoints yet" sub="Waypoints are reading reflections tied to specific page numbers. Start one from any book detail page."/>}
</div>;}

// ─── PROFILE ─────────────────────────────────────────────────
function ProfileScreen({T,user=ME}){
const[tab,setTab]=useState("posts");const[following,setFollowing]=useState(false);const isMe=user.id===ME.id;const tier=gT(user.ink);const lens=LN[user.lens];
const userPosts=FI.filter(f=>f.user.id===user.id);
return <div style={{animation:"en .35s ease both"}}>
<Card T={T} pad="24px 16px" mb={16}><div style={{display:"flex",alignItems:"center",gap:14,marginBottom:16}}><Av T={T} i={user.in} ink={user.ink} s={56}/><div style={{flex:1}}><div style={{fontFamily:T.hd,fontSize:22,fontWeight:700,color:T.tx}}>{user.name}</div><div style={{fontFamily:T.ui,fontSize:12,color:T.tx4,marginTop:2}}>{user.h}</div><div style={{display:"flex",gap:6,marginTop:6}}><IB T={T} ink={user.ink}/><LB T={T} lens={user.lens}/></div></div>
{isMe?<button className="tb" style={{padding:"8px 16px",borderRadius:8,border:`1px solid ${T.bdr}`,background:"transparent",fontFamily:T.ui,fontSize:11,fontWeight:600,color:T.tx3,cursor:"pointer",minHeight:40}}>Edit</button>:<button className="tb" onClick={()=>setFollowing(f=>!f)} style={{padding:"8px 16px",borderRadius:8,border:`1px solid ${following?T.bdr:T.acc}`,background:following?"transparent":T.acc,fontFamily:T.ui,fontSize:11,fontWeight:700,color:following?T.tx3:"#fff",cursor:"pointer",minHeight:40}}>{following?"Following":"Follow"}</button>}
</div>
{user.bio&&<div style={{fontFamily:T.bd,fontSize:13,color:T.tx2,fontStyle:"italic",lineHeight:1.6,marginBottom:16}}>{user.bio}</div>}
<div style={{display:"flex",gap:20,fontFamily:T.ui,fontSize:12}}><div><strong style={{color:T.tx,fontSize:16}}>{user.posts||userPosts.length}</strong><div style={{color:T.tx4,fontSize:10}}>Posts</div></div><div><strong style={{color:T.tx,fontSize:16}}>{user.followers||0}</strong><div style={{color:T.tx4,fontSize:10}}>Followers</div></div><div><strong style={{color:T.tx,fontSize:16}}>{user.following||0}</strong><div style={{color:T.tx4,fontSize:10}}>Following</div></div><div><strong style={{color:T.tx,fontSize:16}}>{user.booksRead||0}</strong><div style={{color:T.tx4,fontSize:10}}>Books Read</div></div></div>
<div style={{marginTop:16,padding:"12px 14px",borderRadius:10,background:`${tier.c}08`,border:`1px solid ${tier.c}15`}}><div style={{display:"flex",alignItems:"center",justifyContent:"space-between"}}><div><div style={{fontFamily:T.ui,fontSize:10,fontWeight:700,color:tier.c,letterSpacing:".06em",textTransform:"uppercase"}}>{tier.name}</div><div style={{fontFamily:T.mn,fontSize:20,fontWeight:700,color:tier.c}}>{fN(user.ink)}</div></div><div style={{width:80,height:4,borderRadius:2,background:`${tier.c}15`}}><div style={{width:`${Math.min((user.ink/(TIERS[TIERS.findIndex(t=>t===tier)+1]?.min||2000))*100,100)}%`,height:"100%",borderRadius:2,background:tier.c}}/></div></div></div></Card>
<div style={{display:"flex",gap:0,marginBottom:14,borderBottom:`1px solid ${T.bdr}`}}>{[{id:"posts",l:"Posts"},{id:"shelves",l:"Shelves"},{id:"about",l:"About"}].map(t=><button key={t.id} className="tb" onClick={()=>setTab(t.id)} style={{padding:"10px 16px",border:"none",cursor:"pointer",fontFamily:T.ui,fontSize:12,fontWeight:tab===t.id?700:500,background:"transparent",color:tab===t.id?T.tx:T.tx3,borderBottom:tab===t.id?`2px solid ${T.acc}`:"2px solid transparent"}}>{t.l}</button>)}</div>
{tab==="posts"&&<div style={{display:"flex",flexDirection:"column",gap:10}}>{userPosts.length===0?<Empty T={T} icon="✎" title="No posts yet" sub={isMe?"Your first post earns +10 Ink.":"Nothing posted yet."}/>:userPosts.map((item,i)=><Card key={item.id} T={T} pad="14px 16px"><div style={{fontFamily:T.hd,fontSize:15,fontWeight:600,color:T.tx,marginBottom:4}}>{item.title||item.bookRef?.title}</div><div style={{fontFamily:T.bd,fontSize:12,color:T.tx3,lineHeight:1.5}}>{item.text.slice(0,120)}…</div><div style={{fontFamily:T.ui,fontSize:10,color:T.tx4,marginTop:6}}>♡ {item.likes} · <MessageCircle size={9} style={{verticalAlign:"middle"}}/> {item.comments} · ◆ {item.shelved}</div></Card>)}</div>}
{tab==="shelves"&&<div style={{display:"flex",flexDirection:"column",gap:8}}>{SHELF_ITEMS.slice(0,3).map(s=><Card key={s.id} T={T} pad="12px 14px"><div style={{fontFamily:T.hd,fontSize:14,fontWeight:600,color:T.tx}}>{s.title||s.book?.title}</div><div style={{fontFamily:T.ui,fontSize:10,color:T.tx4,marginTop:2}}>by {s.authorName} · Shelved {s.shelvedAt}</div></Card>)}</div>}
{tab==="about"&&<Card T={T} pad="16px"><div style={{fontFamily:T.ui,fontSize:10,fontWeight:700,color:T.tx4,letterSpacing:".08em",textTransform:"uppercase",marginBottom:10}}>Reader Identity</div><div style={{display:"flex",gap:8,flexWrap:"wrap",marginBottom:16}}><IB T={T} ink={user.ink}/><LB T={T} lens={user.lens}/></div><div style={{fontFamily:T.ui,fontSize:10,fontWeight:700,color:T.tx4,letterSpacing:".08em",textTransform:"uppercase",marginBottom:8}}>Reading Stats</div><div style={{fontFamily:T.bd,fontSize:13,color:T.tx2,lineHeight:1.8}}>{user.booksRead||0} books read · Member since Jan 2026</div></Card>}
</div>;}

// ─── MESSAGES ────────────────────────────────────────────────
function MessagesScreen({T}){
const[active,setActive]=useState(null);
if(active){const c=CONVOS.find(x=>x.id===active);return <div style={{animation:"en .3s ease both"}}><button className="tb" onClick={()=>setActive(null)} style={{fontFamily:T.ui,fontSize:12,color:T.tx3,background:"none",border:"none",cursor:"pointer",marginBottom:14,minHeight:40}}>← Back</button><Card T={T} pad="16px"><div style={{display:"flex",alignItems:"center",gap:10,marginBottom:16,paddingBottom:12,borderBottom:`1px solid ${T.bdr}`}}><Av T={T} i={c.user.in} ink={c.user.ink} s={36}/><div><div style={{fontFamily:T.ui,fontSize:13,fontWeight:700,color:T.tx}}>{c.user.name}</div><IB T={T} ink={c.user.ink} compact/></div></div>
<div style={{minHeight:200,display:"flex",flexDirection:"column",justifyContent:"flex-end",gap:8,marginBottom:16}}>
<div style={{alignSelf:"flex-start",maxWidth:"80%",padding:"10px 14px",borderRadius:"14px 14px 14px 4px",background:T.bg2}}><div style={{fontFamily:T.bd,fontSize:13,color:T.tx2,lineHeight:1.5}}>{c.lastMsg}</div><div style={{fontFamily:T.ui,fontSize:9,color:T.tx4,marginTop:4}}>{c.time} ago</div></div>
<div style={{alignSelf:"flex-end",maxWidth:"80%",padding:"10px 14px",borderRadius:"14px 14px 4px 14px",background:`${T.acc}15`}}><div style={{fontFamily:T.bd,fontSize:13,color:T.tx,lineHeight:1.5}}>I'll take a closer look at that section tonight.</div><div style={{fontFamily:T.ui,fontSize:9,color:T.tx4,marginTop:4}}>Just now</div></div></div>
<div style={{display:"flex",gap:8}}><input placeholder="Write a message…" style={{flex:1,padding:"12px 14px",borderRadius:10,background:T.bg2,border:`1px solid ${T.bdr}`,fontFamily:T.ui,fontSize:13,color:T.tx,outline:"none"}}/><button className="tb" style={{padding:"10px 18px",borderRadius:10,border:"none",background:T.acc,color:"#fff",fontFamily:T.ui,fontSize:12,fontWeight:700,cursor:"pointer",minHeight:44}}>Send</button></div></Card></div>;}
return <div style={{animation:"en .35s ease both"}}><Sec T={T} title="Messages"><div style={{display:"flex",flexDirection:"column",gap:8}}>{CONVOS.map(c=><button key={c.id} className="tb" onClick={()=>setActive(c.id)} style={{display:"flex",alignItems:"center",gap:10,padding:"14px 16px",borderRadius:14,background:T.sf,border:`1px solid ${c.unread?T.bdrA:T.bdr}`,cursor:"pointer",width:"100%",textAlign:"left",minHeight:60}}><div style={{position:"relative"}}><Av T={T} i={c.user.in} ink={c.user.ink} s={40}/>{c.unread>0&&<div style={{position:"absolute",top:-2,right:-2,width:16,height:16,borderRadius:"50%",background:T.acc,fontFamily:T.ui,fontSize:9,fontWeight:700,color:"#fff",display:"flex",alignItems:"center",justifyContent:"center"}}>{c.unread}</div>}</div><div style={{flex:1,minWidth:0}}><div style={{display:"flex",justifyContent:"space-between",marginBottom:2}}><span style={{fontFamily:T.ui,fontSize:13,fontWeight:c.unread?700:600,color:T.tx}}>{c.user.name}</span><span style={{fontFamily:T.ui,fontSize:10,color:T.tx4}}>{c.time}</span></div><div style={{fontFamily:T.bd,fontSize:12,color:c.unread?T.tx2:T.tx3,overflow:"hidden",textOverflow:"ellipsis",whiteSpace:"nowrap"}}>{c.lastMsg}</div></div></button>)}</div></Sec></div>;}

// ─── NOTIFICATIONS ───────────────────────────────────────────
function NotifsScreen({T}){return <div style={{animation:"en .35s ease both"}}><Sec T={T} title="Notifications"><div style={{display:"flex",flexDirection:"column",gap:4}}>{NOTIFS.map(n=><div key={n.id} style={{display:"flex",alignItems:"center",gap:10,padding:"12px 14px",borderRadius:10,background:n.read?"transparent":`${T.acc}04`,border:`1px solid ${n.read?T.bdr:T.bdrA}`}}><Av T={T} i={n.actor.in} ink={n.actor.ink} s={34}/><div style={{flex:1}}><div style={{fontFamily:T.ui,fontSize:12,color:T.tx2,lineHeight:1.5}}><strong style={{color:T.tx,fontWeight:700}}>{n.actor.name}</strong> {n.action} <strong style={{color:T.tx}}>{n.target}</strong></div><div style={{fontFamily:T.ui,fontSize:10,color:T.tx4,marginTop:2}}>{n.time} ago</div></div>{!n.read&&<div style={{width:8,height:8,borderRadius:"50%",background:T.acc,flexShrink:0}}/>}</div>)}</div></Sec></div>;}

// ─── BOOK CLUBS ──────────────────────────────────────────────
function ClubsScreen({T}){return <div style={{animation:"en .35s ease both"}}><Sec T={T} title="Book Clubs" action={<button className="tb" style={{padding:"8px 14px",borderRadius:8,border:"none",background:T.acc,color:"#fff",fontFamily:T.ui,fontSize:11,fontWeight:700,cursor:"pointer",minHeight:36}}>+ Create</button>}><div style={{display:"flex",flexDirection:"column",gap:10}}>{CLUBS.map(c=><Card key={c.id} T={T} pad="16px"><div style={{display:"flex",justifyContent:"space-between",alignItems:"flex-start"}}><div><div style={{fontFamily:T.hd,fontSize:16,fontWeight:700,color:T.tx,marginBottom:2}}>{c.name}</div><div style={{fontFamily:T.bd,fontSize:12,color:T.tx3,fontStyle:"italic",lineHeight:1.5,marginBottom:6}}>{c.desc}</div><div style={{display:"flex",gap:8,fontFamily:T.ui,fontSize:10,color:T.tx4}}><span style={{display:"inline-flex",alignItems:"center",gap:2}}><BookOpen size={9}/>{c.book}</span><span>·</span><span>{c.members} members</span></div></div>{c.active?<span style={{padding:"4px 10px",borderRadius:6,fontFamily:T.ui,fontSize:9,fontWeight:700,color:T.gn,background:`${T.gn}0D`}}>Active</span>:<span style={{padding:"4px 10px",borderRadius:6,fontFamily:T.ui,fontSize:9,fontWeight:600,color:T.tx4,background:`${T.tx4}08`}}>Completed</span>}</div></Card>)}</div></Sec></div>;}

// ─── CHALLENGES ──────────────────────────────────────────────
function ChallengesScreen({T}){return <div style={{animation:"en .35s ease both"}}><Sec T={T} title="Challenges" sub="Reading goals with Ink rewards"><div style={{display:"flex",flexDirection:"column",gap:10}}>{CHALLENGES.map(ch=><Card key={ch.id} T={T} pad="16px"><div style={{display:"flex",justifyContent:"space-between",alignItems:"flex-start",marginBottom:10}}><div><div style={{fontFamily:T.hd,fontSize:16,fontWeight:700,color:T.tx,marginBottom:2}}>{ch.title}</div><div style={{fontFamily:T.bd,fontSize:12,color:T.tx3,lineHeight:1.5}}>{ch.desc}</div></div><span style={{fontFamily:T.ui,fontSize:10,fontWeight:700,color:T.gold,background:`${T.gold}0D`,padding:"3px 8px",borderRadius:4,flexShrink:0}}>+{ch.reward} Ink</span></div>
<div style={{display:"flex",alignItems:"center",gap:10,marginBottom:8}}><div style={{flex:1,height:6,borderRadius:3,background:`${T.gold}10`}}><div style={{width:`${(ch.progress/ch.goal)*100}%`,height:"100%",borderRadius:3,background:`linear-gradient(90deg,${T.acc},${T.gold})`}}/></div><span style={{fontFamily:T.mn,fontSize:11,fontWeight:600,color:T.tx2}}>{ch.progress}/{ch.goal}</span></div>
<div style={{display:"flex",justifyContent:"space-between",alignItems:"center"}}><span style={{fontFamily:T.ui,fontSize:10,color:T.tx4}}>Ends in {ch.endsIn}</span>{ch.joined?<span style={{fontFamily:T.ui,fontSize:10,fontWeight:700,color:T.gn}}>✓ Joined</span>:<button className="tb" style={{padding:"7px 14px",borderRadius:8,border:"none",background:T.acc,color:"#fff",fontFamily:T.ui,fontSize:11,fontWeight:700,cursor:"pointer",minHeight:36}}>Join</button>}</div></Card>)}</div></Sec></div>;}

// ─── SETTINGS ────────────────────────────────────────────────
function SettingsScreen({T,tid,setTid}){
const[notifs,setN]=useState({likes:true,comments:true,follows:true,clubs:true,challenges:true});
const[priv,setP]=useState({showReading:true,showLocation:false,publicProfile:true});
function Tog({on,onToggle,label}){return <div style={{display:"flex",justifyContent:"space-between",alignItems:"center",padding:"12px 0",borderBottom:`1px solid ${T.bdr}`}}><span style={{fontFamily:T.ui,fontSize:13,color:T.tx}}>{label}</span><button className="tb" onClick={onToggle} style={{width:44,height:26,borderRadius:13,background:on?T.acc:`${T.tx4}30`,border:"none",cursor:"pointer",position:"relative",transition:"background .2s"}}><div style={{width:20,height:20,borderRadius:"50%",background:"#fff",position:"absolute",top:3,left:on?21:3,transition:"left .2s",boxShadow:"0 1px 3px rgba(0,0,0,.2)"}}/></button></div>;}
return <div style={{animation:"en .35s ease both"}}>
<Sec T={T} title="Settings">
<Card T={T} pad="16px" mb={14}><div style={{fontFamily:T.ui,fontSize:10,fontWeight:700,color:T.tx4,letterSpacing:".08em",textTransform:"uppercase",marginBottom:8}}>Account</div><div style={{display:"flex",alignItems:"center",gap:10,padding:"12px 0",borderBottom:`1px solid ${T.bdr}`}}><Av T={T} i={ME.in} ink={ME.ink} s={40}/><div style={{flex:1}}><div style={{fontFamily:T.ui,fontSize:13,fontWeight:600,color:T.tx}}>{ME.name}</div><div style={{fontFamily:T.ui,fontSize:11,color:T.tx4}}>{ME.h}</div></div><button className="tb" style={{fontFamily:T.ui,fontSize:11,color:T.acc,background:"none",border:"none",cursor:"pointer"}}>Edit</button></div></Card>
<Card T={T} pad="16px" mb={14}><div style={{fontFamily:T.ui,fontSize:10,fontWeight:700,color:T.tx4,letterSpacing:".08em",textTransform:"uppercase",marginBottom:8}}>Theme</div><div style={{display:"flex",gap:6,flexWrap:"wrap"}}>{Object.values(THEMES).map(t=>{const a=t.id===tid;return <button key={t.id} className="tb" onClick={()=>setTid(t.id)} style={{display:"flex",alignItems:"center",gap:8,padding:"10px 14px",borderRadius:10,border:`1px solid ${a?`${t.acc}30`:T.bdr}`,background:a?`${t.acc}08`:"transparent",cursor:"pointer",minHeight:44}}><div style={{display:"flex",gap:3}}>{[t.bg,t.sf,t.tx,t.acc].map((c,i)=><div key={i} style={{width:12,height:12,borderRadius:"50%",background:c,border:"1px solid rgba(128,128,128,.12)"}}/>)}</div><span style={{fontFamily:T.ui,fontSize:12,fontWeight:a?700:500,color:a?t.acc:T.tx2}}>{t.name}</span></button>})}</div></Card>
<Card T={T} pad="16px" mb={14}><div style={{fontFamily:T.ui,fontSize:10,fontWeight:700,color:T.tx4,letterSpacing:".08em",textTransform:"uppercase",marginBottom:4}}>Notifications</div>{Object.entries(notifs).map(([k,v])=><Tog key={k} on={v} onToggle={()=>setN(p=>({...p,[k]:!p[k]}))} label={k.charAt(0).toUpperCase()+k.slice(1)}/>)}</Card>
<Card T={T} pad="16px" mb={14}><div style={{fontFamily:T.ui,fontSize:10,fontWeight:700,color:T.tx4,letterSpacing:".08em",textTransform:"uppercase",marginBottom:4}}>Privacy</div>{Object.entries(priv).map(([k,v])=><Tog key={k} on={v} onToggle={()=>setP(p=>({...p,[k]:!p[k]}))} label={k==="showReading"?"Show currently reading":k==="showLocation"?"Show on Reader Map":"Public profile"}/>)}</Card>
<Card T={T} pad="16px"><div style={{fontFamily:T.ui,fontSize:10,fontWeight:700,color:T.tx4,letterSpacing:".08em",textTransform:"uppercase",marginBottom:8}}>Data</div><div style={{display:"flex",flexDirection:"column",gap:8}}><button className="tb" style={{padding:"10px 14px",borderRadius:8,border:`1px solid ${T.bdr}`,background:"transparent",fontFamily:T.ui,fontSize:12,color:T.tx3,cursor:"pointer",textAlign:"left",minHeight:44}}>Import from Goodreads / StoryGraph</button><button className="tb" style={{padding:"10px 14px",borderRadius:8,border:`1px solid ${T.bdr}`,background:"transparent",fontFamily:T.ui,fontSize:12,color:T.tx3,cursor:"pointer",textAlign:"left",minHeight:44}}>Export my data</button><button className="tb" style={{padding:"10px 14px",borderRadius:8,border:`1px solid ${T.rd}15`,background:`${T.rd}04`,fontFamily:T.ui,fontSize:12,color:T.rd,cursor:"pointer",textAlign:"left",minHeight:44}}>Delete account</button></div></Card>
</Sec></div>;}

// ─── COMPOSE ─────────────────────────────────────────────────
function ComposeScreen({T,onClose,initialType=null,initialBook=null}){
const[type,setType]=useState(initialType);
const[book,setBook]=useState(initialBook);
const[bookQ,setBookQ]=useState("");
const[title,setTitle]=useState("");
const[body,setBody]=useState("");
const[published,setPub]=useState(false);
const types=[{id:"original",label:"Original Work",desc:"Fiction, poetry, essays",icon:"✎"},{id:"review",label:"Review",desc:"Your take on a book",icon:"◈"},{id:"recommendation",label:"Recommendation",desc:"Share a must-read",icon:"⬨"},{id:"spoiler",label:"Spoiler Zone",desc:"Discuss freely with warnings",icon:"⚠"}];
const needsBook=type==="review"||type==="recommendation"||type==="spoiler";
const allBooks=Object.values(BOOK_DATA).concat(MY_BOOKS.filter(b=>!BOOK_DATA[b.title]).map(b=>({...b,cc:null})));
const bookResults=bookQ.trim()?allBooks.filter(b=>(b.title||"").toLowerCase().includes(bookQ.toLowerCase())||(b.author||"").toLowerCase().includes(bookQ.toLowerCase())):allBooks;

if(published)return <div style={{animation:"en .3s ease both",textAlign:"center",padding:"60px 16px"}}><div style={{fontSize:48,marginBottom:16}}>✓</div><div style={{fontFamily:T.hd,fontSize:22,fontWeight:700,color:T.tx,marginBottom:8}}>Published!</div><div style={{fontFamily:T.bd,fontSize:13,color:T.tx3,marginBottom:20}}>Your post is live. +5 Ink earned.</div><button className="tb" onClick={onClose} style={{padding:"12px 24px",borderRadius:10,border:"none",background:T.acc,color:"#fff",fontFamily:T.ui,fontSize:13,fontWeight:700,cursor:"pointer",minHeight:44}}>Back to Feed</button></div>;

if(!type)return <div style={{animation:"en .3s ease both"}}><div style={{display:"flex",justifyContent:"space-between",alignItems:"center",marginBottom:20}}><h2 style={{fontFamily:T.hd,fontSize:22,fontWeight:700,color:T.tx}}>New Post</h2><button className="tb" onClick={onClose} style={{fontFamily:T.ui,fontSize:13,color:T.tx3,background:"none",border:"none",cursor:"pointer",minHeight:40}}>✕</button></div><div style={{display:"flex",flexDirection:"column",gap:10}}>{types.map(t=><button key={t.id} className="tb" onClick={()=>setType(t.id)} style={{display:"flex",alignItems:"center",gap:14,padding:"18px 16px",borderRadius:14,background:T.sf,border:`1px solid ${T.bdr}`,cursor:"pointer",textAlign:"left",minHeight:60}}><span style={{fontSize:24,width:40,textAlign:"center"}}>{t.icon}</span><div><div style={{fontFamily:T.ui,fontSize:14,fontWeight:700,color:T.tx}}>{t.label}</div><div style={{fontFamily:T.ui,fontSize:11,color:T.tx3}}>{t.desc}</div></div></button>)}</div></div>;

if(needsBook&&!book)return <div style={{animation:"en .3s ease both"}}>
<div style={{display:"flex",alignItems:"center",gap:10,marginBottom:20}}>
<button className="tb" onClick={()=>initialType?onClose():setType(null)} style={{fontFamily:T.ui,fontSize:12,color:T.tx3,background:"none",border:"none",cursor:"pointer",minHeight:40}}>← Back</button>
<div style={{flex:1}}><div style={{fontFamily:T.hd,fontSize:18,fontWeight:700,color:T.tx}}>Attach a Book</div><div style={{fontFamily:T.bd,fontSize:11,color:T.tx3,fontStyle:"italic",marginTop:1}}>Search for the book you're writing about</div></div>
<TT T={T} type={type}/>
</div>
<div style={{position:"relative",marginBottom:14}}>
<input autoFocus value={bookQ} onChange={e=>setBookQ(e.target.value)} placeholder="Search by title or author…" style={{width:"100%",padding:"12px 14px 12px 36px",borderRadius:10,background:T.bg2,border:`1px solid ${bookQ?T.bdrA:T.bdr}`,fontFamily:T.ui,fontSize:13,color:T.tx,outline:"none"}}/>
<span style={{position:"absolute",left:12,top:"50%",transform:"translateY(-50%)",fontSize:14,color:T.tx4,pointerEvents:"none"}}>⌕</span>
</div>
<div style={{display:"flex",flexDirection:"column",gap:8,maxHeight:"55vh",overflowY:"auto"}}>
{bookResults.map((b,i)=><button key={i} className="tb" onClick={()=>setBook({title:b.title,author:b.author,cc:b.cc||null})} style={{display:"flex",alignItems:"center",gap:12,padding:"12px 14px",borderRadius:12,background:T.sf,border:`1px solid ${T.bdr}`,cursor:"pointer",textAlign:"left",width:"100%",minHeight:56}}>
<div style={{width:30,height:44,borderRadius:"2px 4px 4px 2px",background:`linear-gradient(145deg,${b.cc||T.acc}CC,${b.cc||T.acc||T.acc}60)`,boxShadow:"2px 0 6px rgba(0,0,0,.25)",flexShrink:0}}/>
<div style={{flex:1,minWidth:0}}><div style={{fontFamily:T.hd,fontSize:14,fontWeight:700,color:T.tx,overflow:"hidden",textOverflow:"ellipsis",whiteSpace:"nowrap"}}>{b.title}</div><div style={{fontFamily:T.bd,fontSize:11,color:T.tx3,fontStyle:"italic",marginTop:1}}>{b.author}</div>{b.genres&&<div style={{fontFamily:T.ui,fontSize:9,color:T.tx4,marginTop:3}}>{b.genres.slice(0,2).join(" · ")}</div>}</div>
<span style={{fontFamily:T.ui,fontSize:11,color:T.acc,flexShrink:0}}>Select →</span>
</button>)}
{bookResults.length===0&&<div style={{textAlign:"center",padding:"32px 16px",fontFamily:T.bd,fontSize:13,color:T.tx3,fontStyle:"italic"}}>No books found for "{bookQ}"</div>}
</div>
<button className="tb" onClick={()=>setBook({title:"",author:"",cc:null})} style={{width:"100%",marginTop:14,padding:"12px 0",borderRadius:10,border:`1px solid ${T.bdr}`,background:"transparent",fontFamily:T.ui,fontSize:12,fontWeight:600,color:T.tx4,cursor:"pointer"}}>Skip — write without attaching a book</button>
</div>;

return <div style={{animation:"en .3s ease both"}}>
<div style={{display:"flex",justifyContent:"space-between",alignItems:"center",marginBottom:16}}>
<div style={{display:"flex",alignItems:"center",gap:8}}>
<button className="tb" onClick={()=>initialBook?onClose():setBook(null)} style={{fontFamily:T.ui,fontSize:12,color:T.tx3,background:"none",border:"none",cursor:"pointer",minHeight:40}}>← Back</button>
<TT T={T} type={type}/>
</div>
<button className="tb" onClick={()=>setPub(true)} disabled={!body.trim()} style={{padding:"8px 20px",borderRadius:8,border:"none",background:body.trim()?T.acc:`${T.tx4}20`,color:body.trim()?"#fff":T.tx4,fontFamily:T.ui,fontSize:12,fontWeight:700,cursor:body.trim()?"pointer":"default",minHeight:40}}>Publish</button>
</div>
{book?.title&&<div style={{display:"flex",alignItems:"center",gap:10,padding:"10px 12px",borderRadius:10,background:T.bg2,border:`1px solid ${T.bdrA}`,marginBottom:14}}>
<div style={{width:24,height:36,borderRadius:"2px 3px 3px 2px",flexShrink:0,background:`linear-gradient(140deg,${book.cc||T.acc}90,${book.cc||T.acc}50)`,boxShadow:"1px 0 4px rgba(0,0,0,.2)"}}/>
<div style={{flex:1,minWidth:0}}><div style={{fontFamily:T.ui,fontSize:12,fontWeight:700,color:T.tx}}>{book.title}</div><div style={{fontFamily:T.ui,fontSize:10,color:T.tx3}}>{book.author}</div></div>
<button className="tb" onClick={()=>setBook(null)} style={{background:"none",border:"none",color:T.tx4,cursor:"pointer",fontSize:16,minWidth:28,minHeight:28,display:"flex",alignItems:"center",justifyContent:"center"}}>✕</button>
</div>}
{(type==="original"||type==="review"||type==="spoiler")&&<input value={title} onChange={e=>setTitle(e.target.value)} placeholder="Title…" style={{width:"100%",padding:"12px 0",borderRadius:0,background:"transparent",border:"none",borderBottom:`1px solid ${T.bdr}`,fontFamily:T.hd,fontSize:20,fontWeight:600,color:T.tx,outline:"none",marginBottom:12}}/>}
<textarea value={body} onChange={e=>setBody(e.target.value)} placeholder={type==="original"?"Start writing…":"Share your thoughts…"} rows={8} style={{width:"100%",padding:"12px 0",background:"transparent",border:"none",fontFamily:T.bd,fontSize:14.5,lineHeight:1.7,color:T.tx2,outline:"none",resize:"vertical",minHeight:200}}/>
<div style={{display:"flex",alignItems:"center",gap:12,marginTop:16,paddingTop:12,borderTop:`1px solid ${T.bdr}`}}><span style={{fontFamily:T.mn,fontSize:10,color:T.tx4}}>{body.split(/\s+/).filter(Boolean).length} words</span>{type==="original"&&<span style={{fontSize:8,padding:"2px 6px",borderRadius:3,background:`${T.gn}0D`,color:T.gn,fontFamily:T.ui,fontWeight:700}}>✓ These words are mine</span>}</div>
</div>;}

// ─── THEME PICKER ────────────────────────────────────────────
function TP({T,tid,setTid}){const[open,setOpen]=useState(false);const ref=useRef(null);useEffect(()=>{if(!open)return;const h=e=>{if(ref.current&&!ref.current.contains(e.target))setOpen(false);};document.addEventListener("mousedown",h);document.addEventListener("touchstart",h);return()=>{document.removeEventListener("mousedown",h);document.removeEventListener("touchstart",h);};},[open]);
return <div ref={ref} style={{position:"relative"}}><button className="tb" onClick={()=>setOpen(!open)} style={{width:34,height:34,borderRadius:"50%",border:`1.5px solid ${T.bdr}`,background:T.bg2,cursor:"pointer",display:"flex",alignItems:"center",justifyContent:"center",fontSize:13}}>{THEMES[tid].icon}</button>{open&&<div style={{position:"absolute",top:"calc(100% + 8px)",right:0,background:T.sf,border:`1px solid ${T.bdrA}`,borderRadius:14,padding:6,minWidth:210,boxShadow:T.shL,zIndex:200,animation:"si .12s ease"}}><div style={{padding:"6px 12px 8px",fontFamily:T.ui,fontSize:9,fontWeight:700,color:T.tx4,letterSpacing:".08em",textTransform:"uppercase"}}>Reading Theme</div>{Object.values(THEMES).map(t=>{const a=t.id===tid;return <button key={t.id} className="tb" onClick={()=>{setTid(t.id);setOpen(false);}} style={{display:"flex",alignItems:"center",gap:10,padding:"10px 12px",borderRadius:10,border:"none",cursor:"pointer",width:"100%",minHeight:44,background:a?`${t.acc}0D`:"transparent"}}><div style={{display:"flex",gap:3}}>{[t.bg,t.sf,t.tx,t.acc,t.gold].map((c,i)=><div key={i} style={{width:10,height:10,borderRadius:"50%",background:c,border:"1px solid rgba(128,128,128,.12)"}}/>)}</div><span style={{fontFamily:T.ui,fontSize:12,fontWeight:a?700:500,color:a?t.acc:T.tx2}}>{t.name}</span>{a&&<span style={{marginLeft:"auto",fontSize:10,color:t.acc}}>✓</span>}</button>})}</div>}</div>;}

