// ─── LOGIN / REGISTER SCREEN ─────────────────────────────────
function AuthScreen({T,onAuth}){
const[mode,setMode]=useState("login");
const[email,setEmail]=useState("");
const[password,setPw]=useState("");
const[username,setUn]=useState("");
const[lens,setLens]=useState("explorer");
const[loading,setLoading]=useState(false);
const[error,setError]=useState("");

const submit=async(e)=>{
  e.preventDefault();setError("");setLoading(true);
  try{
    let result;
    if(mode==="login"){result=await API.login({email,password});}
    else{result=await API.register({username,handle:"@"+username.toLowerCase().replace(/\s+/g,"_"),email,password,lens});}
    onAuth(result.user);
  }catch(err){setError(err.message||"Something went wrong");}
  finally{setLoading(false);}
};

return <div style={{minHeight:"100vh",background:T.bg,display:"flex",flexDirection:"column",alignItems:"center",justifyContent:"center",padding:24}}>
<div style={{fontFamily:T.hd,fontSize:32,fontWeight:700,color:T.tx,marginBottom:4}}>Pr<span style={{color:T.acc}}>é</span>cis</div>
<div style={{fontFamily:T.bd,fontSize:13,color:T.tx3,fontStyle:"italic",marginBottom:32}}>A literary social reading app</div>
<div style={{width:"100%",maxWidth:360,background:T.sf,borderRadius:16,border:`1px solid ${T.bdr}`,padding:28}}>
<div style={{display:"flex",gap:0,marginBottom:24,borderBottom:`1px solid ${T.bdr}`}}>
{["login","register"].map(m=><button key={m} className="tb" onClick={()=>{setMode(m);setError("");}} style={{flex:1,padding:"10px",border:"none",cursor:"pointer",fontFamily:T.ui,fontSize:13,fontWeight:mode===m?700:500,background:"transparent",color:mode===m?T.tx:T.tx3,borderBottom:mode===m?`2px solid ${T.acc}`:"2px solid transparent"}}>{m==="login"?"Sign In":"Create Account"}</button>)}
</div>
{error&&<div style={{background:`${T.rd}10`,border:`1px solid ${T.rd}30`,borderRadius:8,padding:"10px 14px",fontFamily:T.ui,fontSize:12,color:T.rd,marginBottom:16}}>{error}</div>}
<form onSubmit={submit}>
{mode==="register"&&<>
<div style={{marginBottom:14}}>
<div style={{fontFamily:T.ui,fontSize:11,fontWeight:600,color:T.tx3,marginBottom:5}}>USERNAME</div>
<input value={username} onChange={e=>setUn(e.target.value)} placeholder="your name" required style={{width:"100%",padding:"10px 14px",borderRadius:10,background:T.bg2,border:`1px solid ${T.bdr}`,fontFamily:T.ui,fontSize:13,color:T.tx,outline:"none"}}/>
</div>
<div style={{marginBottom:14}}>
<div style={{fontFamily:T.ui,fontSize:11,fontWeight:600,color:T.tx3,marginBottom:5}}>READING LENS</div>
<select value={lens} onChange={e=>setLens(e.target.value)} style={{width:"100%",padding:"10px 14px",borderRadius:10,background:T.bg2,border:`1px solid ${T.bdr}`,fontFamily:T.ui,fontSize:13,color:T.tx,outline:"none"}}>
{["analyst","empath","philosopher","storyteller","explorer","alchemist"].map(l=><option key={l} value={l}>{l.charAt(0).toUpperCase()+l.slice(1)}</option>)}
</select>
</div>
</>}
<div style={{marginBottom:14}}>
<div style={{fontFamily:T.ui,fontSize:11,fontWeight:600,color:T.tx3,marginBottom:5}}>EMAIL</div>
<input type="email" value={email} onChange={e=>setEmail(e.target.value)} placeholder="you@example.com" required style={{width:"100%",padding:"10px 14px",borderRadius:10,background:T.bg2,border:`1px solid ${T.bdr}`,fontFamily:T.ui,fontSize:13,color:T.tx,outline:"none"}}/>
</div>
<div style={{marginBottom:20}}>
<div style={{fontFamily:T.ui,fontSize:11,fontWeight:600,color:T.tx3,marginBottom:5}}>PASSWORD</div>
<input type="password" value={password} onChange={e=>setPw(e.target.value)} placeholder="••••••••" required minLength={6} style={{width:"100%",padding:"10px 14px",borderRadius:10,background:T.bg2,border:`1px solid ${T.bdr}`,fontFamily:T.ui,fontSize:13,color:T.tx,outline:"none"}}/>
</div>
<button type="submit" disabled={loading} style={{width:"100%",padding:"12px",borderRadius:10,border:"none",background:loading?T.tx4:T.acc,color:"#fff",fontFamily:T.ui,fontSize:13,fontWeight:700,cursor:loading?"default":"pointer"}}>
{loading?"Please wait…":mode==="login"?"Sign In →":"Create Account →"}
</button>
</form>
<div style={{marginTop:16,textAlign:"center",fontFamily:T.ui,fontSize:11,color:T.tx4}}>
Demo: maya@precis.app / precis123
</div>
</div>
</div>;}

export default function PrecisApp(){
const{T,tid,setTid}=useTheme();const[tab,setTab]=useState("feed");const[feed,setFeed]=useState(FI);
// API integration state
const[apiUser,setApiUser]=useState(()=>API.getStoredUser());
const[feedCursor,setFeedCursor]=useState(null);
const[hasMoreFeed,setHasMoreFeed]=useState(true);
const[feedLoading,setFeedLoading]=useState(false);
// loadFeed: fetch personalized feed from API, append=true for pagination
const loadFeed=useCallback(async(cursor=null,append=false)=>{
  if(feedLoading)return;
  setFeedLoading(true);
  try{
    const result=await API.getFeed(cursor,20);
    const mapped=(result.posts||[]).map(p=>({
      id:p.id,type:p.type,
      user:{id:p.user.id,name:p.user.username,handle:p.user.handle,in:(p.user.username||"?").slice(0,2).toUpperCase(),ink:p.user.ink||0,lens:p.user.lens||"explorer"},
      time:fTime(p.createdAt),text:p.content,tags:p.tags||[],
      bookRef:p.book?{title:p.book.title,author:p.book.author,cc:(p.book.metadata||{}).cc||"#5A7AB4"}:null,
      likes:p.likes||0,comments:p.comments||0,shelved:p.saves||0,reposts:0,
      isLiked:p.isLiked||false,isShelved:p.isSaved||false,isReposted:false,following:true,
    }));
    setFeed(prev=>append?[...prev,...mapped]:(mapped.length>0?mapped:FI));
    setFeedCursor(result.nextCursor);
    setHasMoreFeed(!!result.nextCursor);
  }catch(err){
    console.warn("[feed] API error, using mock data:",err.message);
    if(!append)setFeed(FI);
  }finally{setFeedLoading(false);}
// eslint-disable-next-line react-hooks/exhaustive-deps
},[]);
// Initial feed load when user is authenticated
useEffect(()=>{if(apiUser){loadFeed(null,false);}else{setFeed(FI);setHasMoreFeed(false);}},
// eslint-disable-next-line react-hooks/exhaustive-deps
[apiUser?.id]);
const[searchQ,setSearchQ]=useState("");const[searchOpen,setSO]=useState(false);const[subView,setSV]=useState(null);const[activeBook,setAB]=useState(null);const[readerBook,setRB]=useState(null);const[viewedUser,setVU]=useState(null);
const[composeInit,setCI]=useState({type:null,book:null});
const onBook=useCallback((title,author)=>{setAB({title,author});setSV(null);},[]);
const onReview=useCallback((book)=>{setCI({type:"review",book});setSV("compose");setAB(null);},[]);
const onUser=useCallback((user)=>{if(user.id===ME.id){setTab("profile");setSV(null);setVU(null);}else{setVU(user);setSV("user");setAB(null);}},[]);

const onToggle=useCallback((id,type)=>{setFeed(prev=>prev.map(item=>{if(item.id!==id)return item;if(type==="like"){if(apiUser)API.toggleInteraction(id,"like").catch(()=>{});return{...item,isLiked:!item.isLiked,likes:item.likes+(item.isLiked?-1:1)};}if(type==="shelf"){if(apiUser)API.toggleInteraction(id,"save").catch(()=>{});return{...item,isShelved:!item.isShelved,shelved:item.shelved+(item.isShelved?-1:1)};}if(type==="repost")return{...item,isReposted:!item.isReposted,reposts:item.reposts+(item.isReposted?-1:1)};return item;}));},[]);
const unread=NOTIFS.filter(n=>!n.read).length;const msgUnread=CONVOS.reduce((a,c)=>a+c.unread,0);

function renderMain(){
if(activeBook){const bd=BOOK_DATA[activeBook.title]||activeBook;return <BookDetailScreen T={T} book={bd} onClose={()=>setAB(null)} onRead={()=>setRB(activeBook)} onReview={onReview}/>;}
if(subView==="compose")return <ComposeScreen T={T} onClose={()=>{setSV(null);setCI({type:null,book:null});}} initialType={composeInit.type} initialBook={composeInit.book}/>;
if(subView==="profile")return <ProfileScreen T={T}/>;
if(subView==="user"&&viewedUser)return <ProfileScreen T={T} user={viewedUser}/>;
if(subView==="messages")return <MessagesScreen T={T}/>;
if(subView==="notifications")return <NotifsScreen T={T}/>;
if(subView==="clubs")return <ClubsScreen T={T}/>;
if(subView==="challenges")return <ChallengesScreen T={T}/>;
if(subView==="settings")return <SettingsScreen T={T} tid={tid} setTid={setTid}/>;
if(tab==="feed")return <FeedScreen T={T} feed={feed} onToggle={onToggle} onBook={onBook} onUser={onUser} searchQ={searchQ} loadMore={()=>loadFeed(feedCursor,true)} feedLoading={feedLoading} hasMoreFeed={hasMoreFeed}/>;
if(tab==="explore")return <ExploreScreen T={T} onBook={onBook}/>;
if(tab==="shelf")return <ShelfScreen T={T} onBook={onBook}/>;
if(tab==="profile")return <ProfileScreen T={T}/>;
return null;}

// Show auth screen when not logged in (optional — shows mock data without auth)
if(!apiUser){return <div style={{minHeight:"100vh",background:T.bg,color:T.tx}}><style>{gc(T)}</style><AuthScreen T={T} onAuth={(user)=>{setApiUser(user);setFeed([]);}}/></div>;}
if(readerBook){const bd=BOOK_DATA[readerBook.title]||readerBook;return <div style={{minHeight:"100vh",background:T.bg,color:T.tx}}><style>{gc(T)}</style><ReaderScreen T={T} book={bd} onClose={()=>setRB(null)}/></div>;}
return <div style={{minHeight:"100vh",background:T.bg,color:T.tx,paddingBottom:72}}>
<style>{gc(T)}</style>

{/* MOBILE HEADER */}
<header className="mh" style={{position:"sticky",top:0,zIndex:100,background:`${T.bg}EC`,backdropFilter:"blur(20px) saturate(1.3)",borderBottom:`1px solid ${T.bdr}`,padding:"0 16px",height:52,display:"flex",alignItems:"center",gap:10}}>
{(subView||activeBook)?<button className="tb" onClick={()=>{setSV(null);setAB(null);setVU(null);}} style={{fontFamily:T.ui,fontSize:14,color:T.tx3,background:"none",border:"none",cursor:"pointer",minWidth:36,minHeight:36}}>←</button>:<span style={{fontFamily:T.hd,fontSize:22,fontWeight:700,color:T.tx,letterSpacing:"-.02em",flexShrink:0}}>Pr<span style={{color:T.acc}}>é</span>cis</span>}
<div style={{flex:1}}/>
{searchOpen&&<div style={{flex:1,position:"relative",animation:"fi .15s ease"}}><input autoFocus value={searchQ} onChange={e=>setSearchQ(e.target.value)} placeholder="Search…" style={{width:"100%",padding:"8px 12px 8px 30px",borderRadius:8,background:T.bg3,border:`1px solid ${T.bdrA}`,fontFamily:T.ui,fontSize:13,color:T.tx,outline:"none"}}/><span style={{position:"absolute",left:10,top:"50%",transform:"translateY(-50%)",fontSize:13,color:T.tx4,pointerEvents:"none"}}>⌕</span></div>}
<button className="tb" onClick={()=>{setSO(!searchOpen);if(searchOpen)setSearchQ("");}} style={{background:"none",border:"none",fontSize:18,color:searchOpen?T.acc:T.tx3,cursor:"pointer",padding:4,minWidth:36,minHeight:36,display:"flex",alignItems:"center",justifyContent:"center"}}>{searchOpen?"✕":"⌕"}</button>
<button className="tb" onClick={()=>setSV(sv=>sv==="notifications"?null:"notifications")} style={{background:"none",border:"none",fontSize:16,color:T.tx3,cursor:"pointer",padding:4,minWidth:36,minHeight:36,display:"flex",alignItems:"center",justifyContent:"center",position:"relative"}}><Bell size={16}/>{unread>0&&<div style={{position:"absolute",top:2,right:2,width:14,height:14,borderRadius:"50%",background:T.acc,fontFamily:T.ui,fontSize:8,fontWeight:700,color:"#fff",display:"flex",alignItems:"center",justifyContent:"center"}}>{unread}</div>}</button>
<button className="tb" onClick={()=>setSV(sv=>sv==="messages"?null:"messages")} style={{background:"none",border:"none",fontSize:16,color:T.tx3,cursor:"pointer",padding:4,minWidth:36,minHeight:36,display:"flex",alignItems:"center",justifyContent:"center",position:"relative"}}>✉{msgUnread>0&&<div style={{position:"absolute",top:2,right:2,width:14,height:14,borderRadius:"50%",background:T.acc,fontFamily:T.ui,fontSize:8,fontWeight:700,color:"#fff",display:"flex",alignItems:"center",justifyContent:"center"}}>{msgUnread}</div>}</button>
<button className="tb" onClick={()=>setSV(sv=>sv==="settings"?null:"settings")} style={{background:"none",border:"none",color:subView==="settings"?T.acc:T.tx4,cursor:"pointer",padding:4,minWidth:36,minHeight:36,display:"flex",alignItems:"center",justifyContent:"center"}}><Settings size={16}/></button>
</header>

{/* DESKTOP HEADER */}
<header className="dh" style={{display:"none",position:"sticky",top:0,zIndex:100,background:`${T.bg}E8`,backdropFilter:"blur(20px) saturate(1.3)",borderBottom:`1px solid ${T.bdr}`}}>
<div style={{maxWidth:1040,margin:"0 auto",padding:"0 28px",height:56,display:"flex",alignItems:"center"}}>
<span style={{fontFamily:T.hd,fontSize:24,fontWeight:700,color:T.tx,letterSpacing:"-.02em",marginRight:32,flexShrink:0,cursor:"pointer"}} onClick={()=>{setTab("feed");setSV(null);}}>Pr<span style={{color:T.acc}}>é</span>cis</span>
<div style={{display:"flex",gap:1}}>{TABS.map(n=><button key={n.id} className="tb" onClick={()=>{setTab(n.id);setSV(null);}} style={{padding:"8px 14px",borderRadius:8,border:"none",fontFamily:T.ui,fontSize:12.5,fontWeight:tab===n.id&&!subView?700:500,cursor:"pointer",background:tab===n.id&&!subView?T.gs:"transparent",color:tab===n.id&&!subView?T.gold:T.tx3,display:"flex",alignItems:"center",gap:5}}><span style={{fontSize:14}}>{n.icon}</span> {n.label}</button>)}</div>
<div style={{display:"flex",gap:1,marginLeft:8}}>{[{id:"clubs",l:"Clubs"},{id:"challenges",l:"Challenges"}].map(n=><button key={n.id} className="tb" onClick={()=>setSV(n.id)} style={{padding:"8px 12px",borderRadius:8,border:"none",fontFamily:T.ui,fontSize:12,fontWeight:subView===n.id?700:500,cursor:"pointer",background:subView===n.id?T.gs:"transparent",color:subView===n.id?T.gold:T.tx4}}>{n.l}</button>)}</div>
<div style={{flex:1,maxWidth:240,margin:"0 20px",position:"relative"}}><input value={searchQ} onChange={e=>setSearchQ(e.target.value)} placeholder="Search…" style={{width:"100%",padding:"8px 14px 8px 32px",borderRadius:8,background:T.bg3,border:`1px solid ${searchQ?T.bdrA:T.bdr}`,fontFamily:T.ui,fontSize:12,color:T.tx,outline:"none"}}/><span style={{position:"absolute",left:11,top:"50%",transform:"translateY(-50%)",fontSize:13,color:T.tx4,pointerEvents:"none"}}>⌕</span></div>
<div style={{flex:1}}/>
<button className="tb" onClick={()=>{setCI({type:null,book:null});setSV("compose");}} style={{padding:"8px 20px",borderRadius:8,border:"none",background:T.acc,color:"#fff",fontFamily:T.ui,fontSize:12,fontWeight:700,cursor:"pointer",boxShadow:`0 2px 8px ${T.acc}30`,display:"flex",alignItems:"center",gap:5,marginRight:10}}>✎ Write</button>
<button className="tb" onClick={()=>setSV(sv=>sv==="notifications"?null:"notifications")} style={{background:"none",border:"none",fontSize:16,color:T.tx3,cursor:"pointer",padding:6,position:"relative"}}><Bell size={16}/>{unread>0&&<div style={{position:"absolute",top:0,right:0,width:14,height:14,borderRadius:"50%",background:T.acc,fontFamily:T.ui,fontSize:8,fontWeight:700,color:"#fff",display:"flex",alignItems:"center",justifyContent:"center"}}>{unread}</div>}</button>
<button className="tb" onClick={()=>setSV(sv=>sv==="messages"?null:"messages")} style={{background:"none",border:"none",fontSize:16,color:T.tx3,cursor:"pointer",padding:6,marginRight:8,position:"relative"}}>✉{msgUnread>0&&<div style={{position:"absolute",top:0,right:0,width:14,height:14,borderRadius:"50%",background:T.acc,fontFamily:T.ui,fontSize:8,fontWeight:700,color:"#fff",display:"flex",alignItems:"center",justifyContent:"center"}}>{msgUnread}</div>}</button>
<TP T={T} tid={tid} setTid={setTid}/>
<button className="tb" onClick={()=>{setTab("profile");setSV(null);}} style={{display:"flex",alignItems:"center",gap:8,marginLeft:8,cursor:"pointer",background:"none",border:"none"}}><Av T={T} i={ME.in} ink={ME.ink} s={32}/><div style={{lineHeight:1.2,textAlign:"left"}}><div style={{fontFamily:T.ui,fontSize:12,fontWeight:600,color:T.tx}}>{ME.name}</div><IB T={T} ink={ME.ink} compact/></div></button>
</div></header>

{/* CONTENT */}
<div style={{padding:"16px 14px 0"}} className="fw"><div className={tab==="feed"&&!subView?"fs":""}><main>{renderMain()}</main>
{tab==="feed"&&!subView&&<aside className="sd" style={{display:"none",flexDirection:"column",gap:14,position:"sticky",top:76,animation:"en .4s ease .1s both"}}>
<Card T={T} pad="16px 16px 8px"><div style={{fontFamily:T.hd,fontSize:16,fontWeight:600,color:T.tx,marginBottom:12}}>Trending Now</div>{TRD.map((b,i)=><div key={i} style={{display:"flex",alignItems:"center",gap:10,padding:"10px 4px",borderBottom:i<TRD.length-1?`1px solid ${T.bdr}`:"none",minHeight:48}}><div style={{fontFamily:T.mn,fontSize:11,fontWeight:500,color:T.tx4,width:18,textAlign:"center"}}>{i+1}</div><div style={{width:22,height:32,borderRadius:3,flexShrink:0,background:`linear-gradient(140deg,${b.c}AA,${b.c}60)`}}/><div style={{flex:1,minWidth:0}}><div style={{fontFamily:T.ui,fontSize:12,fontWeight:600,color:T.tx}}>{b.title}</div><div style={{fontFamily:T.ui,fontSize:10,color:T.tx3}}>{b.author}</div></div><span style={{fontFamily:T.mn,fontSize:10,fontWeight:500,color:T.gn,background:`${T.gn}0D`,padding:"2px 6px",borderRadius:3}}>{b.heat}</span></div>)}</Card>
<Card T={T} pad="16px 16px 8px"><div style={{fontFamily:T.hd,fontSize:16,fontWeight:600,color:T.tx,marginBottom:12}}>Ink Leaders</div>{[...US].sort((a,b)=>b.ink-a.ink).slice(0,5).map((u,i)=><div key={u.id} style={{display:"flex",alignItems:"center",gap:8,padding:"8px 2px",borderBottom:i<4?`1px solid ${T.bdr}`:"none"}}><div style={{fontFamily:T.mn,fontSize:11,fontWeight:500,color:i<3?T.gold:T.tx4,width:16}}>{i+1}</div><Av T={T} i={u.in} ink={u.ink} s={26}/><div style={{flex:1,fontFamily:T.ui,fontSize:11.5,fontWeight:600,color:T.tx}}>{u.name}</div><span style={{fontFamily:T.mn,fontSize:10,fontWeight:500,color:gT(u.ink).c}}>{fN(u.ink)}</span></div>)}</Card>
<div style={{padding:"10px 0",fontFamily:T.ui,fontSize:10,color:T.tx4,lineHeight:1.8}}><div style={{display:"flex",gap:12,flexWrap:"wrap",marginBottom:4}}>{["About","TOS","Privacy"].map(l=><span key={l} style={{cursor:"pointer"}}>{l}</span>)}</div>© 2026 Précis Technologies, Inc.</div>
</aside>}</div></div>

{/* MOBILE BOTTOM BAR */}
<nav className="bb" style={{position:"fixed",bottom:0,left:0,right:0,zIndex:100,background:`${T.bg}F2`,backdropFilter:"blur(20px) saturate(1.3)",borderTop:`1px solid ${T.bdr}`,display:"flex",alignItems:"stretch",height:"calc(60px + env(safe-area-inset-bottom))",paddingBottom:"env(safe-area-inset-bottom)"}}>
{TABS.slice(0,2).map(t=>{const a=tab===t.id&&!subView;return <button key={t.id} className="tb" onClick={()=>{setTab(t.id);setSV(null);}} style={{flex:1,display:"flex",flexDirection:"column",alignItems:"center",justifyContent:"center",gap:2,background:"none",border:"none",cursor:"pointer",color:a?T.gold:T.tx4,minHeight:48,position:"relative"}}>{a&&<div style={{position:"absolute",top:0,left:"50%",transform:"translateX(-50%)",width:20,height:2,borderRadius:1,background:T.gold}}/>}<span style={{fontSize:20,lineHeight:1}}>{t.icon}</span><span style={{fontFamily:T.ui,fontSize:9,fontWeight:a?700:500}}>{t.label}</span></button>;})}
<div style={{flex:1,display:"flex",flexDirection:"column",alignItems:"center",justifyContent:"flex-end",paddingBottom:8,position:"relative"}}>
<div onClick={()=>{setCI({type:null,book:null});setSV("compose");}} style={{position:"absolute",top:-22,width:52,height:52,borderRadius:"50%",background:`linear-gradient(135deg,${T.acc},#9A4520)`,boxShadow:`0 4px 16px ${T.acc}50`,display:"flex",alignItems:"center",justifyContent:"center",cursor:"pointer",zIndex:10}}><span style={{fontSize:22,color:"#fff",marginTop:-1}}>✎</span></div>
<span style={{fontFamily:T.ui,fontSize:9,fontWeight:500,color:T.tx4,marginTop:2}}>Publish</span>
</div>
{TABS.slice(2).map(t=>{const a=tab===t.id&&!subView;return <button key={t.id} className="tb" onClick={()=>{setTab(t.id);setSV(null);}} style={{flex:1,display:"flex",flexDirection:"column",alignItems:"center",justifyContent:"center",gap:2,background:"none",border:"none",cursor:"pointer",color:a?T.gold:T.tx4,minHeight:48,position:"relative"}}>{a&&<div style={{position:"absolute",top:0,left:"50%",transform:"translateX(-50%)",width:20,height:2,borderRadius:1,background:T.gold}}/>}{t.id==="profile"?<div style={{width:26,height:26,borderRadius:"50%",border:`2px solid ${a?T.gold:"transparent"}`,overflow:"hidden",flexShrink:0,display:"flex",alignItems:"center",justifyContent:"center"}}><Av T={T} i={ME.in} ink={ME.ink} s={22}/></div>:<span style={{fontSize:20,lineHeight:1}}>{t.icon}</span>}<span style={{fontFamily:T.ui,fontSize:9,fontWeight:a?700:500}}>{t.label}</span></button>;})}
</nav>
</div>;}
